            return Ok(false);\n        };\n        if !lease.leased\n            || lease.revoked_at.is_some()\n            || lease.lease_deadline() <= std::time::Duration::from_secs(clock)\n        {\n            return Ok(false);\n        }\n        lease.revoked_at = Some(clock.max(lease.issued));\n        self.local_revocation_changed(clock)?;\n        Ok(true)\n    }\n\n    pub(super) fn revoke_prefix(&mut self, prefix: &str, clock: u64) -> bool {\n        let boundary = format!(\"{prefix}/\");\n        let mut changed = false;\n        for lease in self.issued.values_mut() {\n            if lease.leased\n                && (lease.lease_id == prefix || lease.lease_id.starts_with(&boundary))\n                && lease.revoked_at.is_none()\n                && lease.lease_deadline() > std::time::Duration::from_secs(clock)\n            {\n                lease.revoked_at = Some(clock.max(lease.issued));\n                changed = true;\n            }\n        }\n        if changed {\n            self.mark_local_crl_dirty();\n        }\n        changed\n    }\n\n    pub(super) fn lease_ids<'a>(&'a self) -> impl Iterator<Item = &'a str> + 'a {\n        self.issued\n            .values()\n            .filter(|v| v.leased)\n            .map(|v| v.lease_id.as_str())\n    }\n\n    pub(super) fn handle_admin(\n        &mut self,\n        method: &str,\n        path: &str,\n        body: &Value,\n        now: u64,\n    ) -> Result<EngineResponse> {\n        if path == \"revoke\" && self.root.is_none() && self.has_external_signer_history() {\n            if !write_method(method) {\n                return Err(unsupported());\n            }\n            reject_unknown(body, &[\"serial_number\"])?;\n            let serial = self.resolve_certificate_serial(string(body, \"serial_number\")?)?;\n            self.external_leaf_issuer_reference(&serial)?;\n            let issued = self.issued.get_mut(&serial).ok_or_else(not_found)?;\n            let changed = issued.revoked_at.is_none();\n            let at = *issued.revoked_at.get_or_insert(now.max(issued.issued));\n            return Ok(ok(\n                json!({\"revocation_time\":at,\"revocation_time_rfc3339\":timestamp(at),\"state\":\"revoked\"}),\n                changed,\n            ));\n        }\n        if method == \"DELETE\"\n            && let Some(reference) = path.strip_prefix(\"issuer/\")\n            && !reference.is_empty()\n            && !reference.contains('/')\n            && self.external_issuer_key(reference).is_ok()\n        {\n            return self.delete_external_issuer(reference, body, now);\n        }\n        if let Some(response) = self.handle_local_intermediate(method, path, body, now)? {\n            return Ok(response);\n        }\n        if let Some(response) = self.handle_local_crl(method, path, body, now)? {\n            return Ok(response);\n        }\n        if path == \"config/urls\" {\n            return self.handle_urls(method, body);\n        }\n        if path == \"config/cluster\" {\n            return self.handle_cluster_config(method, body);\n        }\n        if path == \"config/acme\" {\n            return self.handle_acme_config(method, body);\n        }\n        if path == \"keys\"\n            && method == \"LIST\"\n            && !self.root.as_ref().is_some_and(RootCa::is_external)\n        {\n            return self.local_key_list(body);\n        }\n        if path == \"certs\" && method == \"LIST\" {\n            return self.certificate_list(body);\n        }\n        if method == \"DELETE\"\n            && let Some(reference) = path.strip_prefix(\"issuer/\")\n            && !reference.contains('/')\n            && !reference.is_empty()\n        {\n            let response = self.local_issuer_delete(reference, body)?;\n            self.maintain_local_crl(now)?;\n            return Ok(response);\n        }\n        if path == \"config/issuers\" {\n            if self.root.as_ref().is_some_and(RootCa::is_external)\n                ||