           uri_sans: &prepared.uri_sans,\n                exclude_cn_from_sans: prepared.exclude_cn_from_sans,\n                max_path_length: None,\n                permitted_dns_domains: &[],\n                role_leaf_profile: prepared.role_leaf_profile.as_ref(),\n            },\n            prepared.role_name_policy.as_ref(),\n        )?;\n        self.publish_leaf(prepared, certificate_der, &leaf_pkcs8, &leaf_public, false)\n    }\n\n    fn publish_leaf(\n        &mut self,\n        prepared: LeafTemplate,\n        certificate_der: Vec<u8>,\n        leaf_pkcs8: &[u8],\n        leaf_public: &LocalPublicKey,\n        external: bool,\n    ) -> Result<EngineResponse> {\n        // The ordinary Vault publication lane cannot admit a public account\n        // owner, even for a no_store response. ACME has its own typed asset.\n        let owner = prepared\n            .owner\n            .vault_owner()\n            .ok_or_else(|| error(503, \"public ACME owner cannot publish a Vault lease\"))?\n            .clone();\n        prepared.validate_publication(prepared.issued)?;\n        let root = self.selected_issuer(if prepared.local_issuer_id.is_empty() {\n            \"default\"\n        } else {\n            &prepared.local_issuer_id\n        })?;\n        if self.issued.contains_key(&prepared.serial) || self.issued.len() >= MAX_ISSUED {\n            return Err(error(503, \"PKI issuance state changed\"));\n        }\n        if let Some(profile) = &prepared.role_leaf_profile {\n            profile.validate_created_leaf_der(&certificate_der)?;\n        }\n        let certificate = public::stored_pem(\"CERTIFICATE\", &certificate_der);\n        let issuing_ca = public::stored_pem(\"CERTIFICATE\", &root.certificate_der);\n        let certificate_end = crate::auth::Timestamp::whole(prepared.expires)\n            .map_err(|_| bad(\"invalid PKI certificate expiry\"))?;\n        let lease_expires = if prepared.leased {\n            if let Some(claims) = owner.batch_claims() {\n                let claimed = match claims.precision() {\n                    Some(lease) => lease.expires_at,\n                    None => crate::auth::Timestamp::whole(claims.expires_at())\n                        .map_err(|_| bad(\"invalid PKI batch lease expiry\"))?,\n                };\n                let retained = match prepared.precise_owner_expires {\n                    Some(end) => end,\n                    None => crate::auth::Timestamp::whole(\n                        prepared.owner_expires.unwrap_or(claims.expires_at()),\n                    )\n                    .map_err(|_| bad(\"invalid retained PKI batch lease expiry\"))?,\n                };\n                let end = certificate_end.min(claimed).min(retained);\n                if end.duration_since_epoch() <= std::time::Duration::from_secs(prepared.issued) {\n                    return Err(error(403, \"issuer no longer has a live PKI lease window\"));\n                }\n                (end < certificate_end).then_some(end)\n            } else {\n                None\n            }\n        } else {\n            None\n        };\n        let ttl = if prepared.leased && owner.batch_claims().is_some() {\n            let time = precise_time::observe(\n                prepared.publication_time,\n                prepared.publication_clock,\n                prepared.issued,\n            )?;\n            let at = time.exact().map_or_else(\n                || std::time::Duration::from_secs(time.seconds()),\n                crate::auth::Timestamp::duration_since_epoch,\n            );\n            let end = lease_expires\n                .unwrap_or(certificate_end)\n                .duration_since_epoch();\n            if end <= at {\n                return Err(error(403, \"issuer no longer has a live PKI lease window\"));\n            }\n            end.saturating_sub(at).as_secs()\n        } else {\n            prepared.expires.saturating_sub(prepared.issued)\n        };\n        let mut data = json!({\"certificate\":certificate, \"issuing_ca\":issuing_ca,\n            \"serial_number\":prepared.serial, \"expiration\":prepared.expires});\n        if prepared.csr_public_key.is_none() {\n            let mut private_key =\n                LocalPrivateMaterial::private_pem(prepared.local_key_kind, leaf_pkcs8, external)?;\n            if private_key.ends_with('\\n') {\n                private_key.pop();\n            }\n            data[\"private_key\"] = json!(private_key.as_str());\n            data[\"private_key_type\"] = json!(prepared.local_key_kind.key_type());\n        } else if !leaf_pkcs8.is_empty() || prepared.csr_public_key.as_ref() != Some(leaf_public) {\n            return Err(bad(\"CSR signed leaf has an unexpected private key owner\"));\n        }\n        data[\"serial_number\"] = json!(external::formatted_serial(&prepared.serial));\n        data[\"ca_chain\"] = if external {\n            json!(self.external_ca_chain_pem(root)?)\n        } else {\n            json!(\n                root.local_ca_chain_pem()\n                    .into_iter()\n                    .map(|mut pem| {\n                        if pem.ends_with('\\n') {\n                            pem.pop();\n                        }\n                        pem\n                    })\n                    .collect::<Vec<_>>()\n            )\n        };\n        data[\"not_before\"] = json!(prepared.not_before);\n        let mut response = EngineResponse {\n            status: 200,\n            body: json!({\"request_id\":\"\", \"lease_id\":if prepared.leased {prepared.lease_id.clone()} else {String::new()},\n                \"renewable\":false,\"lease_duration\":if prepared.leased {ttl} else {0},\"data\":data}),\n            mutated: true,\n        };\n        if !prepared.warnings.is_empty() {\n            response.body[\"warnings\"] = json!(prepared.warnings);\n        }\n        if prepared.no_store {\n            response.mutated = false;\n            return Ok(response);\n        }\n        let role_leaf_profile = LeafProfilePublicEvidence::capture(&prepared, leaf_public);\n        self.issued.insert(\n            prepared.serial.clone(),\n            IssuedCertificate {\n                url_entries: prepared.url_entries,\n                role_names_owned: prepared.role_name_policy.is_some(),\n                issuer_not_after_behavior: prepared.issuer_not_after_behavior,\n                signed_role_time_owned: prepared.signed_role_time_owned,\n                role_time_owned: prepared.role_time_owned,\n                role_leaf_profile,\n                local_issuer_id: prepared.local_issuer_id,\n                external_issuer_owner: None,\n                leased: prepared.leased,\n                lease_id: prepared.lease_id,\n                owner,\n                path: prepared.path,\n                issued: prepared.issued,\n                expires: prepared.expires,\n                lease_expires,\n                revoked_at: None,\n                wildcard_names: prepared.common_name.contains('*')\n                    || prepared.alt_names.iter().any(|name| name.contains('*')),\n                common_name: prepared.common_name,\n                certificate_der,\n            },\n        );\n        Ok(response)\n    }\n\n    fn crl_der(&self, root: &RootCa, _now: u64) -> Result<Vec<u8>> {\n        if root.is_external() {\n            return Err(error(\n                501,\n                \"external PKI CRL requires a qualified signing lane\",\n            ));\n        }\n        Ok(self.cached_local_crl(root, false)?.to_vec())\n    }\n}\n\n// Only the public role input uses the framework's weak boolean conversion.\n// Durable Role deserialization still requires actual booleans; request text\n// is never retained as an authority marker or copied into the stored owner.\nfn role_optional_bool(body: &Value, name: &str) -> Result<Option<bool>> {\n    let Some(value) = body.get(name) else {\n        return Ok(None);\n    };\n    let detail = match value {\n        Value::Bool(value) => return Ok(Some(*value)),\n        Value::Null => return Ok(Some(false)),\n        Value::String(value) => match value.as_str() {\n            \"1\" | \"t\" | \"T\" | \"TRUE\" | \"true\" | \"True\" => return Ok(Some(true)),\n            \"\" | \"0\" | \"f\" | \"F\" | \"FALSE\" | \"false\" | \"False\" => return Ok(Some(false)),\n            _ => \"cannot parse value as 'bool': strconv.ParseBool: invalid syntax\",\n        },\n        Value::Number(value) => match value.to_string().as_str() {\n            \"1\" => return Ok(Some(true)),\n            \"0\" => return Ok(Some(false)),\n            _ => \"cannot parse value as 'bool': strconv.ParseBool: invalid syntax\",\n        },\n        Value::Array(_) => \"expected type 'bool', got unconvertible type '[]interface {}'\",\n        Value::Object(_) => {\n            \"expected type 'bool', got unconvertible type 'map[string]interface {}'\"\n        }\n    };\n    Err(bad(&format!(\n        \"Field validation failed: error converting input for field \\\"{name}\\\": '' {detail}\"\n    )))\n}\n\nimpl Role {\n    fn effective_leaf_profile(&self) -> RoleLeafProfile {\n        self.role_leaf_profile.clone().unwrap_or_default()\n    }\n    fn from_patch(previous: &Self, patch: &Value) -> Result<Self> {\n        let mut merged = SecretJson(previous.descriptor());\n        let output = merged\n            .as_object_mut()\n            .ok_or_else(|| bad(\"invalid stored PKI role\"))?;\n        let patch = patch\n            .as_object()\n            .ok_or_else(|| bad(\"request body must be an object\"))?;\n        for (name, value) in patch {\n            output.insert(name.clone(), value.clone());\n        }\n        let mut role = Self::from_body(&merged)?;\n        if previous.role_time_policy.is_none()\n            && !role_time::ROLE_TIME_FIELDS\n                .iter()\n                .any(|name| patch.get(*name).is_some())\n        {\n            role.role_time_policy = None;\n        }\n        if previous.role_name_policy.is_none()\n            && !role_names::ROLE_NAME_FIELDS\n                .iter()\n                .any(|name| patch.get(*name).is_some())\n        {\n            role.role_name_policy = None;\n        }\n        Ok(role)\n    }\n    fn from_body(body: &Value) -> Result<Self> {\n        let allow_any_name = role_optional_bool(body, \"allow_any_name\")?.unwrap_or(false);\n        let names = RoleNamePolicy::from_body(body)?;\n        let allowed_domains = string_list(body.get(\"allowed_domains\"))?;\n        if allowed_domains.len() > 64\n            || allowed_domains.iter().any(|v| !names.valid_domain_entry(v))\n        {\n            return Err(bad(\"allowed_domains must contain 1..=64 DNS domains\"));\n        }\n        let max_ttl = role_time::role_duration(body, \"max_ttl\", 0)?;\n        let time_policy = RoleTimePolicy::from_body(body, max_ttl)?;\n        let key_policy = RoleKeyPolicy::from_body(body)?;\n        let role = Self {\n            role_key_policy: key_policy.clone(),\n            role_name_policy: Some(names.clone()),\n            role_time_policy: role_time::ROLE_TIME_FIELDS\n                .iter()\n                .any(|name| body.get(*name).is_some())\n                .then_some(time_policy),\n            role_leaf_profile: Some(RoleLeafProfile::from_body(body)?),\n            issuer_ref: match body.get(\"issuer_ref\") {\n                None => String::new(),\n                Some(Value::String(value)) if value == \"default\" => String::new(),\n                Some(Value::String(value))\n                    if !value.is_empty()\n                        && value.len() <= 128\n                        && !value.contains('/')\n                        && !value.chars().any(char::is_control) =>\n                {\n                    value.clone()\n                }\n                _ => return Err(bad(\"invalid PKI role issuer reference\")),\n            },\n            allowed_domains: allowed_domains.into_iter().collect(),\n            allow_any_name,\n            allow_bare_domains: Some(\n                role_optional_bool(body, \"allow_bare_domains\")?.unwrap_or(false),\n            ),\n            allow_wildcard_certificates: Some(\n                role_optional_bool(body, \"allow_wildcard_certificates\")?.unwrap_or(true),\n            ),\n            allow_subdomains: role_optional_bool(body, \"allow_subdomains\")?.unwrap_or(false),\n            allow_ip_sans: role_optional_bool(body, \"allow_ip_sans\")?.unwrap_or(true),\n            max_ttl,\n            generate_lease: !names.no_store\n                && role_optional_bool(body, \"generate_lease\")?.unwrap_or(false),\n            local_key_kind: if key_policy.is_some() {\n                None\n            } else {\n                match LocalKeyKind::from_body(body)? {\n                    LocalKeyKind::Ed25519 => None,\n                    kind => Some(kind),\n                }\n            },\n        };\n        role.validate()?;\n        Ok(role)\n    }\n    fn validate(&self) -> Result<()> {\n        if let Some(policy) = &self.role_key_policy {\n            policy.validate(self)?;\n        }\n        if let Some(names) = &self.role_name_policy {\n            names.validate()?;\n        }\n        if let Some(profile) = &self.role_leaf_profile {\n            profile.validate_role_oid_strings()?;\n            if profile.leaf_subject_evidence.is_some() {\n                return Err(bad(\"role cannot carry captured leaf subject evidence\"));\n            }\n        }\n        if let Some(policy) = &self.role_time_policy {\n            policy.validate(self.max_ttl)?;\n        }\n        if self.issuer_ref.len() > 128\n            || self.issuer_ref.contains('/')\n            || self.issuer_ref.chars().any(char::is_control)\n            || self.local_key_kind == Some(LocalKeyKind::Ed25519)\n            || self.role_name_policy.is_none()\n                && !self.allow_any_name\n                && self.allowed_domains.is_empty()\n            || self.allowed_domains.len() > 64\n            || self.allowed_domains.iter().any(|v| {\n                !self\n                    .role_name_policy\n                    .as_ref()\n                    .map_or_else(|| valid_domain(v), |policy| policy.valid_domain_entry(v))\n            })\n            || self.max_ttl > MAX_TTL\n        {\n            return Err(bad(\"invalid PKI role\"));\n        }\n        Ok(())\n    }\n    fn allows(&self, name: &str) -> bool {\n        let name = name.to_ascii_lowercase();\n        let wildcard = wildcard_name(&name);\n        if name.contains('*')\n            && (self.allow_wildcard_certificates != Some(true) || wildcard.is_none())\n        {\n            return false;\n        }\n        self.allow_any_name\n            || self.allowed_domains.iter().any(|domain| {\n                let domain = domain.to_ascii_lowercase();\n                self.allow_bare_domains.unwrap_or(true) && name == domain\n                    || self.allow_subdomains\n                        && (name.ends_with(&format!(\".{domain}\"))\n                            || wildcard\n                                .is_some_and(|(_, reduced)| reduced.eq_ignore_ascii_case(&domain)))\n            })\n    }\n    fn descriptor(&self) -> Value {\n        let mut descriptor = json!({\n            \"issuer_ref\": if self.issuer_ref.is_empty() {\"default\"} else {self.issuer_ref.as_str()},\n            \"allowed_domains\": self.allowed_domains,\n            \"allow_any_name\": self.allow_any_name,\n            \"allow_bare_domains\": self.allow_bare_domains.unwrap_or(true),\n            \"allow_wildcard_certificates\": self.allow_wildcard_certificates.unwrap_or(false),\n            \"allow_subdomains\": self.allow_subdomains,\n            \"allow_ip_sans\": self.allow_ip_sans,\n            \"max_ttl\": self.max_ttl,\n            \"generate_lease\": self.generate_lease,\n            \"key_type\": \"ed25519\",\n            \"key_bits\": 0,\n        });\n        if let Some(policy) = &self.role_key_policy {\n            policy.descriptor(&mut descriptor);\n        }\n        if let Some(kind) = self.local_key_kind {\n            descriptor[\"key_type\"] = json!(kind.key_type());\n            descriptor[\"key_bits\"] = json!(kind.bits());\n        }\n        {\n            let profile = self.effective_leaf_profile();\n            descriptor[\"allow_token_displayname\"] = json!(false);\n            if let Some(fields) = profile.descriptor_fields().as_object() {\n                for (name, value) in fields {\n                    descriptor[name] = value.clone();\n                }\n            }\n        }\n        if let Some(fields) = self\n            .role_time_policy\n            .clone()\n            .unwrap_or_default()\n            .descriptor()\n            .as_object()\n        {\n            for (name, value) in fields {\n                descriptor[name] = value.clone();\n            }\n        }\n        if let Some(names) = &self.role_name_policy\n            && let Some(fields) = names.descriptor().as_object()\n        {\n            for (name, value) in fields {\n                descriptor[name] = value.clone();\n            }\n        }\n        descriptor\n    }\n}\n\nimpl AcmeConfig {\n    fn descriptor(&self) -> Value {\n        json!({\n            \"allowed_roles\": self.allowed_roles,\n            \"allow_role_ext_key_usage\": self.allow_role_ext_key_usage,\n            \"allowed_issuers\": self.allowed_issuers,\n            \"default_directory_policy\": self.default_directory_policy,\n            \"enabled\": self.enabled,\n            \"dns_resolver\": self.dns_resolver,\n            \"eab_policy\": self.eab_policy,\n        })\n    }\n}\n\nimpl Pki {\n    fn validate_acme_config_write(&self, config: &AcmeConfig) -> Result<()> {\n        // Persisted allowlists retain references after retirement. Validate live\n        // references only on API configuration writes, as the native backend does.\n        let write_error =\n            |message: String| error(500, &format!(\"1 error occurred:\\n\\t* {message}\\n\\n\"));\n        if config.allowed_issuers.len() != 1 || config.allowed_issuers[0] != \"*\" {\n            for (index, name) in config.allowed_issuers.iter().enumerate() {\n                if name == \"*\" {\n                    return Err(write_error(format!(\n                        \"cannot use '*' as issuer name at index {index}\"\n                    )));\n                }\n                self.selected_issuer(name).map_err(|_| write_error(format!(\n                    \"failed validating allowed_issuers: unable to fetch issuer: {name}: unable to find PKI issuer for reference: {name}\")))?;\n            }\n        }\n        for name in config\n            .allowed_roles\n            .iter()\n            .filter(|name| name.as_str() != \"*\")\n        {\n            let role = self.roles.get(name).ok_or_else(|| write_error(format!(\n                \"allowed_role {name} is not a valid acme role: the request message was malformed: role does not exist\")))?;\n            if role\n                .role_name_policy\n                .as_ref()\n                .is_some_and(|names| names.no_store)\n            {\n                return Err(write_error(format!(\n                    \"allowed_role {name} is not a valid acme role: the server experienced an internal error: role can not be used as NoStore is set to true\"\n                )));\n            }\n        }\n        if let Some(name) = config.default_directory_policy.strip_prefix(\"role:\") {\n            let role = self.roles.get(name).ok_or_else(|| write_error(format!(\n                \"default directory policy role {name} is not a valid ACME role: the request message was malformed: role does not exist\")))?;\n            if role\n                .role_name_policy\n                .as_ref()\n                .is_some_and(|names| names.no_store)\n            {\n                return Err(write_error(format!(\n                    \"default directory policy role {name} is not a valid ACME role: the server experienced an internal error: role can not be used as NoStore is set to true\"\n                )));\n            }\n            if config.allowed_roles.as_slice() != [\"*\"]\n                && !config.allowed_roles.iter().any(|allowed| allowed == name)\n            {\n                return Err(write_error(format!(\n                    \"default directory policy {} was not specified in allowed_roles: [{}]\",\n                    config.default_directory_policy,\n                    config.allowed_roles.join(\" \")\n                )));\n            }\n        }\n        Ok(())\n    }\n}\n\nfn validate_acme_config(config: &AcmeConfig) -> Result<()> {\n    validate_acme_names(&config.allowed_roles, \"allowed_roles\")?;\n    if config.allowed_issuers.is_empty()\n        || config.allowed_issuers.len() > MAX_ACME_LIST\n        || config\n            .allowed_issuers\n            .iter()\n            .any(|issuer| issuer.is_empty() || issuer.len() > 128)\n    {\n        return Err(bad(\"invalid ACME allowed_issuers\"));\n    }\n    if config.allowed_issuers.iter().any(|name| {\n        name == \"*\" && config.allowed_issuers.len() != 1 || name != \"*\" && valid_name(name).is_err()\n    }) {\n        return Err(bad(\"invalid ACME allowed_issuers\"));\n    }\n    match config.default_directory_policy.as_str() {\n        \"forbid\" | \"sign-verbatim\" => {}\n        value\n            if value\n                .strip_prefix(\"role:\")\n                .is_some_and(|name| !name.is_empty() && valid_name(name).is_ok()) => {}\n        _ => return Err(bad(\"invalid ACME default_directory_policy\")),\n    }\n    if config.dns_resolver.len() > MAX_ACME_CONFIG_STRING {\n        return Err(bad(\"ACME dns_resolver is too long\"));\n    }\n    if !config.dns_resolver.is_empty() {\n        let address = config\n            .dns_resolver\n            .parse::<SocketAddr>()\n            .map_err(|_| bad(\"ACME dns_resolver must be an IP address and port\"))?;\n        if address.port() == 0 {\n            return Err(bad(\"ACME dns_resolver port must be nonzero\"));\n        }\n    }\n    if config.default_directory_policy.len() > MAX_ACME_CONFIG_STRING\n        || config.eab_policy.len() > MAX_ACME_CONFIG_STRING\n    {\n        return Err(bad(\"ACME configuration string is too long\"));\n    }\n    if !matches!(\n        config.eab_policy.as_str(),\n        \"not-required\" | \"new-account-required\" | \"always-required\"\n    ) {\n        return Err(bad(\"invalid ACME eab_policy\"));\n    }\n    if config.enabled && config.allowed_roles.is_empty() {\n        return Err(bad(\"ACME allowed_roles must not be empty\"));\n    }\n    Ok(())\n}\n\nfn validate_acme_names(values: &[String], field: &str) -> Result<()> {\n    if values.is_empty() || values.len() > MAX_ACME_LIST {\n        return Err(bad(\"ACME name list is outside bounds\"));\n    }\n    if values.iter().any(|value| {\n        value == \"*\" && values.len() != 1 || value != \"*\" && valid_name(value).is_err()\n    }) {\n        return Err(bad(if field == \"allowed_roles\" {\n            \"invalid ACME allowed_roles\"\n        } else {\n            \"invalid ACME name list\"\n        }));\n    }\n    Ok(())\n}\n\nfn ttl_value(value: &Value, default: u64) -> Result<u64> {\n    let ttl = match value {\n        Value::Number(_) => value.as_u64().ok_or_else(|| bad(\"invalid PKI TTL\"))?,\n        Value::String(_) => duration_seconds(value)?,\n        _ => return Err(bad(\"invalid PKI TTL\")),\n    };\n    Ok(if ttl == 0 { default } else { ttl })\n}\n\nfn ttl_field(body: &Value, field: &str, default: u64) -> Result<u64> {\n    body.get(field)\n        .map(|value| match value {\n            Value::Number(_) => value.as_u64().ok_or_else(|| bad(\"invalid PKI TTL\")),\n            Value::String(_) => duration_seconds(value),\n            _ => Err(bad(\"invalid PKI TTL\")),\n        })\n        .transpose()\n        .map(|v| v.unwrap_or(default))\n}\n\nfn string_list(value: Option<&Value>) -> Result<Vec<String>> {\n    match value {\n        None => Ok(Vec::new()),\n        Some(Value::String(value)) => {\n            if value.is_empty() {\n                Ok(Vec::new())\n            } else {\n                Ok(value.split(',').map(|v| v.trim().to_owned()).collect())\n            }\n        }\n        Some(Value::Array(values)) => values\n            .iter()\n            .map(|v| {\n                v.as_str()\n                    .map(str::to_owned)\n                    .ok_or_else(|| bad(\"expected an array of strings\"))\n            })\n            .collect(),\n        Some(_) => Err(bad(\"expected a string or array of strings\")),\n    }\n}\n\nfn ip_list(value: Option<&Value>) -> Result<Vec<IpAddr>> {\n    string_list(value)?\n        .into_iter()\n        .map(|value| {\n            value\n                .parse()\n                .map_err(|_| bad(\"expected valid IP subject alternative names\"))\n        })\n        .collect()\n}\n\nfn valid_name(name: &str) -> Result<()> {\n    if name.is_empty()\n        || name.len() > 128\n        || !name\n            .bytes()\n            .all(|c| c.is_ascii_alphanumeric() || b\"_-\".contains(&c))\n    {\n        return Err(bad(\"invalid PKI role name\"));\n    }\n    Ok(())\n}\nfn valid_domain(name: &str) -> bool {\n    let name = name.trim_end_matches('.');\n    !name.is_empty()\n        && name.len() <= 253\n        && name.split('.').all(|label| {\n            !label.is_empty()\n                && label.len() <= 63\n                && !label.starts_with('-')\n                && !label.ends_with('-')\n                && label\n                    .bytes()\n                    .all(|c| c.is_ascii_alphanumeric() || c == b'-')\n        })\n}\n// RFC6125 wildcard syntax: exactly one star in the leftmost label. Each\n// nonempty part of that label must itself be a DNS label, and all remaining\n// labels remain ordinary DNS names. This does not broaden allowed_domains.\nfn wildcard_name(name: &str) -> Option<(&str, &str)> {\n    let name = name.trim_end_matches('.');\n    if name.is_empty() || name.len() > 253 || name.bytes().filter(|b| *b == b'*').count() != 1 {\n        return None;\n    }\n    let (label, reduced) = name.split_once('.').unwrap_or((name, \"\"));\n    if label.len() > 63 || !label.contains('*') || !reduced.is_empty() && !valid_domain(reduced) {\n        return None;\n    }\n    let (prefix, suffix) = label.split_once('*')?;\n    if [prefix, suffix]\n        .into_iter()\n        .any(|part| !part.is_empty() && !valid_domain(part))\n    {\n        return None;\n    }\n    Some((label, reduced))\n}\n\nfn wildcard_dns_san(name: &str) -> bool {\n    wildcard_name(name).is_some_and(|(label, reduced)| label == \"*\" && !reduced.is_empty())\n}\n\nfn valid_common_name(name: &str) -> bool {\n    valid_domain(name) || wildcard_name(name).is_some()\n}\n\nfn validate_uri(value: &str, field: &str) -> Result<()> {\n    if value.is_empty() {\n        return Ok(());\n    }\n    if value.len() > MAX_ACME_CONFIG_STRING\n        || value\n            .chars()\n            .any(|character| character.is_control() || character.is_whitespace())\n    {\n        return Err(bad(\"PKI URL is outside bounds\"));\n    }\n    let invalid_url = || {\n        let message = if field == \"PKI cluster path\" {\n            \"invalid, non-URL path given to cluster\"\n        } else {\n            \"invalid, non-URL path given to AIA\"\n        };\n        // Keep the upstream status without reflecting credentials or private paths.\n        error(500, message)\n    };\n    let Some((scheme, rest)) = value.split_once(\"://\") else {\n        return Err(invalid_url());\n    };\n    if !matches!(scheme, \"http\" | \"https\") {\n        return Err(invalid_url());\n    }\n    let authority = rest.split(['/', '?', '#']).next().unwrap_or(\"\");\n    if authority.is_empty() || authority.contains('@') {\n        return Err(invalid_url());\n    }\n    Ok(())\n}\n\nfn random_serial() -> Result<String> {\n    let mut serial =\n        crate::crypto::random::<20>().map_err(|_| error(503, \"PKI serial generation failed\"))?;\n    serial[0] &= 0x7f;\n    if serial.iter().all(|v| *v == 0) {\n        serial[19] = 1;\n    }\n    Ok(canonical_serial_bytes(&serial))\n}\n\nfn random_pki_id() -> Result<String> {\n    let bytes = crate::crypto::random::<16>()\n        .map_err(|_| error(503, \"PKI identifier generation failed\"))?;\n    // Native PKI genIssuerId/genKeyId use go-uuid.GenerateUUID, which formats\n    // all 128 entropy bits rather than imposing RFC version/variant bits.\n    Ok(crate::crypto::uuid_from_bytes(&bytes))\n}\n\nfn valid_pki_id(value: &str) -> bool {\n    value.is_empty()\n        || value.len() == 36\n            && value.bytes().enumerate().all(|(index, byte)| {\n                if matches!(index, 8 | 13 | 18 | 23) {\n                    byte == b'-'\n                } else {\n                    byte.is_ascii_hexdigit()\n                }\n            })\n}\nfn canonical_serial_bytes(bytes: &[u8]) -> String {\n    let start = bytes\n        .iter()\n        .position(|b| *b != 0)\n        .unwrap_or(bytes.len() - 1);\n    bytes[start..].iter().map(|b| format!(\"{b:02x}\")).collect()\n}\n\nfn normalize_serial(value: &str) -> Result<String> {\n    let compact: String = value\n        .chars()\n        .filter(|c| *c != ':' && *c != '-')\n        .collect::<String>()\n        .to_ascii_lowercase();\n    serial_bytes(&compact)?;\n    Ok(compact)\n}\nfn serial_bytes(value: &str) -> Result<Vec<u8>> {\n    if value.is_empty()\n        || value.len() > 64\n        || !value.len().is_multiple_of(2)\n        || !value.bytes().all(|c| c.is_ascii_hexdigit())\n    {\n        return Err(bad(\"invalid certificate serial number\"));\n    }\n    (0..value.len())\n        .step_by(2)\n        .map(|i| {\n            u8::from_str_radix(&value[i..i + 2], 16)\n                .map_err(|_| bad(\"invalid certificate serial number\"))\n        })\n        .collect()\n}\n\nstruct IssuanceRoute<'a> {\n    mount: &'a str,\n    role: &'a str,\n    explicit_issuer: Option<&'a str>,\n    sign: bool,\n}\n\npub(super) struct LeafAuthority<'a> {\n    pub(super) owner: &'a LeaseOwner,\n    pub(super) owner_expires: Option<u64>,\n    pub(super) precise_owner_expires: Option<crate::auth::Timestamp>,\n    pub(super) time: crate::auth::AuthorityTime,\n    pub(super) clock: Option<crate::auth::RequestClock>,\n    pub(super) identity_templates: Option<&'a crate::auth::IdentityTemplateValues>,\n}\n\n#[derive(Clone)]\nenum LeafOwner {\n    Vault(LeaseOwner),\n    Acme(acme_certificate::Binding),\n}\nimpl LeafOwner {\n    fn vault_owner(&self) -> Option<&LeaseOwner> {\n        match self {\n            Self::Vault(owner) => Some(owner),\n            Self::Acme(_) => None,\n        }\n    }\n}\nstruct LeafPreparationAuthority<'a> {\n    owner: LeafOwner,\n    owner_expires: Option<u64>,\n    precise_owner_expires: Option<crate::auth::Timestamp>,\n    time: crate::auth::AuthorityTime,\n    clock: Option<crate::auth::RequestClock>,\n    identity_templates: Option<&'a crate::auth::IdentityTemplateValues>,\n}\n#[derive(Clone)]\nstruct LeafTemplate {\n    url_entries: Option<UrlEntries>,\n    csr_public_key: Option<LocalPublicKey>,\n    role_name_policy: Option<RoleNamePolicy>,\n    no_store: bool,\n    exclude_cn_from_sans: bool,\n    email_sans: Vec<String>,\n    uri_sans: Vec<String>,\n    issuer_not_after_behavior: Option<IssuerLeafNotAfterBehavior>,\n    signed_role_time_owned: bool,\n    role_time_owned: bool,\n    warnings: Vec<String>,\n    role_leaf_profile: Option<RoleLeafProfile>,\n    local_issuer_id: String,\n    serial: String,\n    path: String,\n    lease_id: String,\n    owner: LeafOwner,\n    owner_expires: Option<u64>,\n    precise_owner_expires: Option<crate::auth::Timestamp>,\n    publication_time: crate::auth::AuthorityTime,\n    publication_clock: Option<crate::auth::RequestClock>,\n    leased: bool,\n    common_name: String,\n    local_key_kind: LocalKeyKind,\n    alt_names: Vec<String>,\n    ip_sans: Vec<IpAddr>,\n    issued: u64,\n    not_before: i64,\n    expires: u64,\n}\n\nimpl LeafTemplate {\n    fn validate_publication(&self, floor: u64) -> Result<()> {\n        self.validate_publication_observed(crate::auth::AuthorityTime::Coarse(floor))\n    }\n    fn validate_publication_observed(&self, time: crate::auth::AuthorityTime) -> Result<()> {\n        let observed = precise_time::observe(\n            self.publication_time,\n            self.publication_clock,\n            time.seconds(),\n        )?;\n        let observed = match (observed.exact(), time.exact()) {\n            (Some(left), Some(right)) => crate::auth::AuthorityTime::Precise(left.max(right)),\n            (None, Some(right)) => crate::auth::AuthorityTime::Precise(right),\n            _ => observed,\n        };\n        if PkiInstant::whole(self.expires)? <= PkiInstant::authority(observed)?\n            || self\n                .precise_owner_expires\n                .is_some_and(|end| observed.exact().is_none_or(|at| at > end))\n            || self.precise_owner_expires.is_none()\n                && self\n                    .owner_expires\n                    .is_some_and(|end| observed.seconds() >= end)\n        {\n            return Err(error(403, \"issuer no longer has a live PKI lease window\"));\n        }\n        Ok(())\n    }\n}\n\nstruct CertificateSpec<'a> {\n    url_entries: Option<&'a UrlEntries>,\n    role_leaf_profile: Option<&'a RoleLeafProfile>,\n    serial: &'a str,\n    issuer_cn: &'a str,\n    subject_cn: &'a str,\n    issuer_name_der: Option<&'a [u8]>,\n    subject_name_der: Option<&'a [u8]>,\n    public_key: &'a [u8],\n    authority_key_id: Option<&'a [u8]>,\n    not_before: i64,\n    not_after: u64,\n    is_ca: bool,\n    alt_names: &'a [String],\n    email_sans: &'a [String],\n    ip_sans: &'a [IpAddr],\n    uri_sans: &'a [String],\n    exclude_cn_from_sans: bool,\n    max_path_length: Option<u32>,\n    permitted_dns_domains: &'a [String],\n}\n\nfn certificate_der(signer: &Ed25519KeyPair, spec: CertificateSpec<'_>) -> Result<Vec<u8>> {\n    let tbs = certificate_tbs(spec)?;\n    let signature = signer.sign(&tbs);\n    Ok(seq(&[\n        tbs,\n        algorithm_ed25519(),\n        bit_string(signature.as_ref(), 0),\n    ]))\n}\n\nfn certificate_tbs(spec: CertificateSpec<'_>) -> Result<Vec<u8>> {\n    if spec.public_key.len() != 32 {\n        return Err(error(500, \"invalid Ed25519 public key\"));\n    }\n    let spki = seq(&[algorithm_ed25519(), bit_string(spec.public_key, 0)]);\n    certificate_tbs_with(spec, &spki, &algorithm_ed25519())\n}\n\nfn certificate_der_local(\n    signer: &LocalPrivateMaterial,\n    subject: &LocalPublicKey,\n    spec: CertificateSpec<'_>,\n) -> Result<Vec<u8>> {\n    if signer.kind() == LocalKeyKind::Ed25519\n        && let LocalPublicKey::Ed25519(public) = subject\n    {\n        let bytes = signer.private_der()?;\n        let pair = Ed25519KeyPair::from_pkcs8(&bytes)\n            .map_err(|_| error(503, \"invalid local PKI signing key\"))?;\n        return certificate_der(\n            &pair,\n            CertificateSpec {\n                public_key: public,\n                ..spec\n            },\n        );\n    }\n    let algorithm = signer.kind().signature_algorithm();\n    let tbs = certificate_tbs_with(spec, &subject.spki()?, &algorithm)?;\n    let signature = signer.sign(&tbs)?;\n    if !signer.public()?.verify(&tbs, &signature)? {\n        return Err(error(\n            503,\n            \"local PKI certificate signature failed validation\",\n        ));\n    }\n    Ok(seq(&[tbs, algorithm, bit_string(&signature, 0)]))\n}\n\nfn certificate_der_local_with_policy(\n    signer: &LocalPrivateMaterial,\n    subject: &LocalPublicKey,\n    spec: CertificateSpec<'_>,\n    policy: Option<&RoleNamePolicy>,\n) -> Result<Vec<u8>> {\n    let scheme = LeafSignature::for_key(signer.kind(), policy);\n    if matches!(scheme, LeafSignature::Legacy(_)) {\n        return certificate_der_local(signer, subject, spec);\n    }\n    let algorithm = scheme.algorithm();\n    let tbs = certificate_tbs_with(spec, &subject.spki()?, &algorithm)?;\n    let signature = signer.sign_leaf(&tbs, scheme)?;\n    if !signer.public()?.verify_leaf(&tbs, &signature, scheme)? {\n        return Err(error(\n            503,\n            \"local PKI certificate signature failed validation\",\n        ));\n    }\n    Ok(seq(&[tbs, algorithm, bit_string(&signature, 0)]))\n}\n\nfn certificate_tbs_with(\n    spec: CertificateSpec<'_>,\n    subject_spki: &[u8],\n    signature_algorithm: &[u8],\n) -> Result<Vec<u8>> {\n    let CertificateSpec {\n        url_entries,\n        serial,\n        issuer_cn,\n        subject_cn,\n        issuer_name_der,\n        subject_name_der,\n        public_key: _,\n        authority_key_id,\n        not_before,\n        not_after,\n        is_ca,\n        alt_names,\n        email_sans,\n        ip_sans,\n        uri_sans,\n        exclude_cn_from_sans,\n        max_path_length,\n        permitted_dns_domains,\n        role_leaf_profile,\n    } = spec;\n    if is_ca && role_leaf_profile.is_some() {\n        return Err(error(\n            503,\n            \"PKI leaf profile cannot control a CA certificate\",\n        ));\n    }\n    let subject_der = if let Some(profile) = role_leaf_profile {\n        profile.subject_der(subject_cn)?\n    } else {\n        subject_name_der.map_or_else(|| name(subject_cn), <[u8]>::to_vec)\n    };\n    let mut extensions = role_leaf_profile\n        .map(RoleLeafProfile::leaf_extensions)\n        .transpose()?\n        .unwrap_or_default();\n    let basic = if is_ca {\n        let mut fields = vec![boolean(true)];\n        if let Some(length) = max_path_length {\n            fields.push(integer(&length.to_be_bytes()));\n        }\n        seq(&fields)\n    } else {\n        seq(&[])\n    };\n    if role_leaf_profile.is_none() {\n        extensions.push(extension(&[0x55, 0x1d, 0x13], true, &basic));\n    }\n    if !permitted_dns_domains.is_empty() {\n        let subtrees: Vec<_> = permitted_dns_domains\n            .iter()\n            .map(|domain| seq(&[context_primitive(2, domain.as_bytes())]))\n            .collect();\n        extensions.push(extension(\n            &[0x55, 0x1d, 0x1e],\n            true,\n            &seq(&[der(0xa0, &subtrees.concat())]),\n        ));\n    }\n    if let Some(urls) = url_entries {\n        extensions.extend(urls.certificate_extensions()?);\n    }\n    let subject_key_id = root_fields::subject_key_identifier(subject_spki)?;\n    extensions.push(extension(\n        &[0x55, 0x1d, 0x0e],\n        false,\n        &octet_string(&subject_key_id),\n    ));\n    if let Some(authority_key_id) = authority_key_id {\n        extensions.push(extension(\n            &[0x55, 0x1d, 0x23],\n            false,\n            &seq(&[context_primitive(0, authority_key_id)]),\n        ));\n    }\n    let usage_byte = if is_ca { 0x06 } else { 0x80 };\n    let unused = if is_ca { 1 } else { 7 };\n    if role_leaf_profile.is_none() {\n        extensions.push(extension(\n            &[0x55, 0x1d, 0x0f],\n            true,\n            &bit_string(&[usage_byte], unused),\n        ));\n    }\n    let captured_subject =\n        role_leaf_profile.and_then(|profile| profile.leaf_subject_evidence.as_ref());\n    let other_names = captured_subject\n        .map(|subject| subject.other_names_der())\n        .transpose()?\n        .unwrap_or_default();\n    let policies = captured_subject\n        .map(|subject| subject.policies_der())\n        .transpose()?\n        .flatten();\n    let qualified_policy =\n        captured_subject.is_some_and(|subject| subject.policy_uses_extra_extension());\n    if !other_names.is_empty()\n        && !qualified_policy\n        && let Some(policies) = &policies\n    {\n        extensions.push(policies.clone());\n    }\n    let mut names = other_names.clone();\n    if !exclude_cn_from_sans\n        && (role_leaf_profile.is_none() || !subject_cn.is_empty())\n        && (is_ca || !subject_cn.contains('*') || wildcard_dns_san(subject_cn))\n    {\n        names.push(context_primitive(2, subject_cn.as_bytes()));\n    }\n    for name in alt_names {\n        names.push(context_primitive(2, name.as_bytes()));\n    }\n    for email in email_sans {\n        names.push(context_primitive(1, email.as_bytes()));\n    }\n    for ip in ip_sans {\n        let bytes = match ip {\n            IpAddr::V4(ip) => ip.octets().to_vec(),\n            IpAddr::V6(ip) => ip.octets().to_vec(),\n        };\n        names.push(context_primitive(7, &bytes));\n    }\n    for uri in uri_sans {\n        names.push(context_primitive(6, uri.as_bytes()));\n    }\n    if !names.is_empty() {\n        extensions.push(extension(\n            &[0x55, 0x1d, 0x11],\n            subject_der.as_slice() == [0x30, 0] && other_names.is_empty(),\n            &seq(&names),\n        ));\n    }\n    if (other_names.is_empty() || qualified_policy)\n        && let Some(policies) = policies\n    {\n        extensions.push(policies);\n    }\n    let tbs = seq(&[\n        context_explicit(0, &integer(&[2])),\n        integer(&serial_bytes(serial)?),\n        signature_algorithm.to_vec(),\n        issuer_name_der.map_or_else(|| name(issuer_cn), <[u8]>::to_vec),\n        seq(&[time_signed(not_before), time(not_after)]),\n        subject_der,\n        subject_spki.to_vec(),\n        context_explicit(3, &seq(&extensions)),\n    ]);\n    Ok(tbs)\n}\n\nfn extension(oid_value: &[u8], critical: bool, value_der: &[u8]) -> Vec<u8> {\n    let mut parts = vec![oid(oid_value)];\n    if critical {\n        parts.push(boolean(true));\n    }\n    parts.push(octet_string(value_der));\n    seq(&parts)\n}\nfn algorithm_ed25519() -> Vec<u8> {\n    seq(&[oid(&[0x2b, 0x65, 0x70])])\n}\nfn name(common_name: &str) -> Vec<u8> {\n    seq(&[set(&[seq(&[\n        oid(&[0x55, 0x04, 0x03]),\n        utf8(common_name.as_bytes()),\n    ])])])\n}\nfn time(seconds: u64) -> Vec<u8> {\n    time_stamp(&timestamp(seconds))\n}\nfn time_signed(seconds: i64) -> Vec<u8> {\n    time_stamp(&role_time::signed_timestamp(seconds))\n}\nfn time_stamp(stamp: &str) -> Vec<u8> {\n    let bytes = stamp.as_bytes();\n    let year: u32 = stamp[0..4].parse().unwrap_or(2050);\n    if (1950..2050).contains(&year) {\n        let mut value = Vec::with_capacity(13);\n        value.extend_from_slice(&bytes[2..4]);\n        value.extend_from_slice(&bytes[5..7]);\n        value.extend_from_slice(&bytes[8..10]);\n        value.extend_from_slice(&bytes[11..13]);\n        value.extend_from_slice(&bytes[14..16]);\n        value.extend_from_slice(&bytes[17..19]);\n        value.push(b'Z');\n        der(0x17, &value)\n    } else {\n        let mut value = Vec::with_capacity(15);\n        value.extend_from_slice(&bytes[0..4]);\n        value.extend_from_slice(&bytes[5..7]);\n        value.extend_from_slice(&bytes[8..10]);\n        value.extend_from_slice(&bytes[11..13]);\n        value.extend_from_slice(&bytes[14..16]);\n        value.extend_from_slice(&bytes[17..19]);\n        value.push(b'Z');\n        der(0x18, &value)\n    }\n}\nfn der(tag: u8, content: &[u8]) -> Vec<u8> {\n    let mut out = Vec::with_capacity(content.len() + 6);\n    out.push(tag);\n    if content.len() < 128 {\n        out.push(content.len() as u8);\n    } else {\n        let bytes = (content.len() as u64).to_be_bytes();\n        let first = bytes\n            .iter()\n            .position(|v| *v != 0)\n            .unwrap_or(bytes.len() - 1);\n        let len = bytes.len() - first;\n        out.push(0x80 | len as u8);\n        out.extend_from_slice(&bytes[first..]);\n    }\n    out.extend_from_slice(content);\n    out\n}\nfn concat(parts: &[Vec<u8>]) -> Vec<u8> {\n    parts.iter().flat_map(|v| v.iter().copied()).collect()\n}\nfn seq(parts: &[Vec<u8>]) -> Vec<u8> {\n    der(0x30, &concat(parts))\n}\nfn set(parts: &[Vec<u8>]) -> Vec<u8> {\n    der(0x31, &concat(parts))\n}\nfn oid(value: &[u8]) -> Vec<u8> {\n    der(0x06, value)\n}\nfn utf8(value: &[u8]) -> Vec<u8> {\n    der(0x0c, value)\n}\nfn boolean(value: bool) -> Vec<u8> {\n    der(0x01, &[if value { 0xff } else { 0x00 }])\n}\nfn octet_string(value: &[u8]) -> Vec<u8> {\n    der(0x04, value)\n}\nfn integer(value: &[u8]) -> Vec<u8> {\n    let mut body = value\n        .iter()\n        .skip_while(|v| **v == 0)\n        .copied()\n        .collect::<Vec<_>>();\n    if body.is_empty() {\n        body.push(0);\n    }\n    if body[0] & 0x80 != 0 {\n        body.insert(0, 0);\n    }\n    der(0x02, &body)\n}\nfn bit_string(value: &[u8], unused: u8) -> Vec<u8> {\n    let mut body = Vec::with_capacity(value.len() + 1);\n    body.push(unused);\n    body.extend_from_slice(value);\n    der(0x03, &body)\n}\nfn context_explicit(tag: u8, value: &[u8]) -> Vec<u8> {\n    der(0xa0 | tag, value)\n}\nfn context_primitive(tag: u8, value: &[u8]) -> Vec<u8> {\n    der(0x80 | tag, value)\n}\n// Ring generates OneAsymmetricKey (PKCS8 v2). Export PrivateKeyInfo with the\n// maintained provider so consumers accepting standard PKCS8 can load the leaf.\n// Only the response encoding changes; bind the exporter to the original key.\nfn leaf_private_key_pem(pkcs8: &[u8]) -> Result<Zeroizing<String>> {\n    let original = Ed25519KeyPair::from_pkcs8(pkcs8)\n        .map_err(|_| error(503, \"PKI leaf private key export failed\"))?;\n    let provider = openssl::pkey::PKey::private_key_from_der(pkcs8)\n        .map_err(|_| error(503, \"PKI leaf private key export failed\"))?;\n    let public = provider\n        .raw_public_key()\n        .map_err(|_| error(503, \"PKI leaf private key export failed\"))?;\n    if public.as_slice() != original.public_key().as_ref() {\n        return Err(error(503, \"PKI leaf private key export failed\"));\n    }\n    let encoded = Zeroizing::new(\n        provider\n            .private_key_to_pem_pkcs8()\n            .map_err(|_| error(503, \"PKI leaf private key export failed\"))?,\n    );\n    let text = std::str::from_utf8(&encoded)\n        .map_err(|_| error(503, \"PKI leaf private key export failed\"))?;\n    Ok(Zeroizing::new(text.to_owned()))\n}\n\nfn pem(label: &str, der: &[u8]) -> String {\n    let encoded = BASE64.encode(der);\n    let mut out = format!(\"-----BEGIN {label}-----\\n\");\n    for chunk in encoded.as_bytes().chunks(64) {\n        out.push_str(std::str::from_utf8(chunk).unwrap_or(\"\"));\n        out.push('\\n');\n    }\n    out.push_str(&format!(\"-----END {label}-----\\n\"));\n    out\n}\n\nfn private_key_pem(label: &str, der: &[u8]) -> Result<Zeroizing<String>> {\n    let encoded = Zeroizing::new(BASE64.encode(der));\n    let mut out = Zeroizing::new(format!(\"-----BEGIN {label}-----\\n\"));\n    for chunk in encoded.as_bytes().chunks(64) {\n        out.push_str(\n            std::str::from_utf8(chunk).map_err(|_| error(503, \"PKI private key export failed\"))?,\n        );\n        out.push('\\n');\n    }\n    out.push_str(&format!(\"-----END {label}-----\"));\n    Ok(out)\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n\n    #[test]\n    fn pki_leaf_private_export_is_standard_pkcs8_with_original_public_key()\n    -> std::result::Result<(), Box<dyn std::error::Error>> {\n        let document = Zeroizing::new(\n            Ed25519KeyPair::generate_pkcs8(&SystemRandom::new())\n                .map_err(|_| \"temporary key generation\")?\n                .as_ref()\n                .to_vec(),\n        );\n        let original =\n            Ed25519KeyPair::from_pkcs8(&document).map_err(|_| \"original temporary key\")?;\n        let exported = leaf_private_key_pem(&document)?;\n        let loaded = openssl::pkey::PKey::private_key_from_pem(exported.as_bytes())?;\n        assert!(\n            loaded.raw_public_key()?.as_slice() == original.public_key().as_ref(),\n            \"standard private export preserves the original leaf public key\"\n        );\n        let message = b\"synthetic PKCS8 consumer proof\";\n        let signature = original.sign(message);\n        let mut verifier = openssl::sign::Verifier::new_without_digest(&loaded)?;\n        assert!(\n            verifier.verify_oneshot(signature.as_ref(), message)?,\n            \"exported private key verifies the original leaf signature\"\n        );\n        Ok(())\n    }\n\n    #[test]\n    fn internal_root_issue_revoke_and_crl_are_der_structured()\n    -> std::result::Result<(), Box<dyn std::error::Error>> {\n        let mut pki = Pki::default();\n        let root = pki.handle_admin(\n            \"POST\",\n            \"root/generate/internal\",\n            &json!({\"common_name\":\"ca.example.test\",\"ttl\":\"48h\"}),\n            1_700_000_000,\n        )?;\n        assert!(\n            root.body[\"data\"][\"certificate\"]\n                .as_str()\n                .unwrap_or(\"\")\n                .contains(\"BEGIN CERTIFICATE\")\n        );\n        pki.handle_admin(\n            \"POST\",\n            \"roles/web\",\n            &json!({\"allowed_domains\":[\"example.test\"],\"allow_subdomains\":true,\"max_ttl\":\"2h\",\"generate_lease\":true}),\n            1_700_000_001,\n        )?;\n        let issued = pki.issue(\n            \"pki/\",\n            \"web\",\n            &json!({\"common_name\":\"api.example.test\",\"alt_names\":[\"www.example.test\"],\"ttl\":\"1h\"}),\n            &serde_json::from_value::<LeaseOwner>(json!(\"a\".repeat(43)))?,\n            Some(1_700_010_000),\n            1_700_000_002,\n        )?;\n        let serial = issued.body[\"data\"][\"serial_number\"]\n            .as_str()\n            .ok_or(\"serial\")?\n            .to_owned();\n        assert_eq!(issued.body[\"renewable\"], false);\n        assert!(\n            issued.body[\"data\"][\"private_key\"]\n                .as_str()\n                .unwrap_or(\"\")\n                .contains(\"BEGIN RSA PRIVATE KEY\")\n        );\n        let revoked = pki.handle_admin(\n            \"POST\",\n            \"revoke\",\n            &json!({\"serial_number\":serial}),\n            1_700_000_100,\n        )?;\n        assert_eq!(revoked.body[\"data\"][\"revocation_time\"], 1_700_000_100);\n        let crl = pki.handle_admin(\"GET\", \"cert/crl\", &json!({}), 1_700_000_101)?;\n        assert!(\n            crl.body[\"data\"][\"certificate\"]\n                .as_str()\n                .unwrap_or(\"\")\n                .contains(\"BEGIN X509 CRL\")\n        );\n        Ok(())\n    }\n\n    #[test]\n    fn ip_sans_are_role_gated_and_encoded_as_general_name_ip()\n    -> std::result::Result<(), Box<dyn std::error::Error>> {\n        let mut pki = Pki::default();\n        pki.handle_admin(\n            \"POST\",\n            \"root/generate/internal\",\n            &json!({\"common_name\":\"ca.example.test\",\"ttl\":\"48h\"}),\n            1_700_000_000,\n        )?;\n        pki.handle_admin(\n            \"POST\",\n            \"roles/web\",\n            &json!({\"allowed_domains\":[\"example.test\"],\"allow_ip_sans\":false}),\n            1_700_000_001,\n        )?;\n        let denied = pki.issue(\n            \"pki/\",\n            \"web\",\n            &json!({\"common_name\":\"api.example.test\",\"ip_sans\":[\"127.0.0.1\"]}),\n            &serde_json::from_value::<LeaseOwner>(json!(\"a\".repeat(43)))?,\n            None,\n            1_700_000_002,\n        );\n        let denied_status = match denied {\n            Ok(_) => {\n                return Err(\n                    \"role with explicit allow_ip_sans=false unexpectedly issued a certificate\"\n                        .into(),\n                );\n            }\n            Err(error) => error.status,\n        };\n        assert_eq!(denied_status, 400);\n        pki.handle_admin(\n            \"POST\",\n            \"roles/web-ip\",\n            &json!({\"allowed_domains\":[\"example.test\"],\"allow_subdomains\":true,\"allow_ip_sans\":true}),\n            1_700_000_003,\n        )?;\n        let issued = pki.issue(\n            \"pki/\",\n            \"web-ip\",\n            &json!({\"common_name\":\"api.example.test\",\"ip_sans\":[\"127.0.0.1\",\"2001:db8::1\"],\"ttl\":\"1h\"}),\n            &serde_json::from_value::<LeaseOwner>(json!(\"a\".repeat(43)))?,\n            None,\n            1_700_000_004,\n        )?;\n        let cert = issued.body[\"data\"][\"certificate\"]\n            .as_str()\n            .ok_or(\"certificate\")?;\n        let der = BASE64.decode(\n            cert.strip_prefix(\"-----BEGIN CERTIFICATE-----\\n\")\n                .ok_or(\"pem begin\")?\n                .strip_suffix(\"-----END CERTIFICATE-----\")\n                .ok_or(\"pem end\")?\n                .lines()\n                .collect::<String>(),\n        )?;\n        assert!(der.windows(6).any(|v| v == [0x87, 0x04, 127, 0, 0, 1]));\n        assert!(der.windows(18).any(|v| v[0] == 0x87 && v[1] == 0x10));\n        Ok(())\n    }\n\n    #[test]\n    fn acme_configuration_is_bounded_and_serde_stable()\n    -> std::result::Result<(), Box<dyn std::error::Error>> {\n        let mut pki = Pki::default();\n        let cluster = pki.handle_admin(\n            \"POST\",\n            \"config/cluster\",\n            &json!({\n                \"path\":\"https://acme.example.test/v1/pki\",\n                \"aia_path\":\"http://cdn.example.test/pki\"\n            }),\n            1_700_000_000,\n        )?;\n        assert_eq!(\n            cluster.body[\"data\"][\"path\"],\n            \"https://acme.example.test/v1/pki\"\n        );\n        let acme = pki.handle_admin(\n            \"POST\",\n            \"config/acme\",\n            &json!({\"enabled\":true,\"eab_policy\":\"new-account-required\"}),\n            1_700_000_000,\n        )?;\n        assert_eq!(acme.body[\"data\"][\"enabled\"], true);\n        assert_eq!(acme.body[\"data\"][\"eab_policy\"], \"new-account-required\");\n        let unknown = pki.handle_admin(\n            \"POST\",\n            \"config/acme\",\n            &json!({\"enabled\":false,\"unknown\":\"must-not-persist\"}),\n            1_700_000_000,\n        )?;\n        assert_eq!(unknown.status, 200);\n        assert_eq!(unknown.body[\"data\"][\"enabled\"], false);\n        assert_eq!(\n            unknown.body[\"warnings\"],\n            json!([\"Endpoint ignored these unrecognized parameters: [unknown]\"])\n        );\n        assert!(!unknown.body.to_string().contains(\"must-not-persist\"));\n        let after_unknown = pki.handle_admin(\"GET\", \"config/acme\", &json!({}), 1_700_000_000)?;\n        assert_eq!(after_unknown.body[\"data\"][\"enabled\"], false);\n        for (path, body, status) in [\n            (\n                \"config/cluster\",\n                json!({\"path\":\"file:///secret-location\"}),\n                500,\n            ),\n            (\"config/acme\", json!({\"allowed_issuers\":[\"issuer-a\"]}), 500),\n        ] {\n            let rejected = pki.handle_admin(\"POST\", path, &body, 1_700_000_000);\n            assert_eq!(\n                rejected\n                    .as_ref()\n                    .map(|v| v.status)\n                    .unwrap_or_else(|v| v.status),\n                status\n            );\n        }\n        assert_eq!(\n            pki.handle_admin(\"GET\", \"config/acme\", &json!({}), 1_700_000_000)?\n                .body,\n            after_unknown.body\n        );\n        let mut restored: Pki = serde_json::from_slice(&serde_json::to_vec(&pki)?)?;\n        assert_eq!(\n            restored\n                .handle_admin(\"GET\", \"config/cluster\", &json!({}), 1_700_000_000)?\n                .body[\"data\"],\n            cluster.body[\"data\"]\n        );\n        assert_eq!(\n            restored\n                .handle_admin(\"GET\", \"config/acme\", &json!({}), 1_700_000_000)?\n                .body[\"data\"],\n            after_unknown.body[\"data\"]\n        );\n        Ok(())\n    }\n}\n\n#[cfg(test)]\n#[path = \"pki_root_format_tests.rs\"]\nmod root_format_tests;\n\n#[cfg(test)]\nmod bare_domain_legacy_tests {\n    use super::*;\n\n    #[test]\n    fn pki_role_bare_domain_legacy_bytes_keep_actual_historical_permission() -> Result<()> {\n        let legacy = json!({\"allowed_domains\":[\"example.test\"],\"allow_subdomains\":false,\n                           \"allow_ip_sans\":false,\"max_ttl\":3600,\"generate_lease\":false});\n        let historical: Role =\n            serde_json::from_value(legacy.clone()).map_err(|_| bad(\"legacy role fixture\"))?;\n        historical.validate()?;\n        assert!(historical.allow_bare_domains.is_none() && historical.allows(\"example.test\"));\n        assert!(\n            serde_json::to_value(&historical).map_err(|_| bad(\"legacy serialization\"))? == legacy,\n            \"historical role JSON stays exact and has no fabricated default field\"\n        );\n        let current = Role::from_body(&legacy)?;\n        assert!(current.allow_bare_domains == Some(false) && !current.allows(\"example.test\"));\n        let mut body = legacy.clone();\n        body[\"allow_bare_domains\"] = json!(true);\n        let allowed = Role::from_body(&body)?;\n        assert!(allowed.allow_bare_domains == Some(true) && allowed.allows(\"EXAMPLE.TEST\"));\n        for wrong in [json!(\"not_bool\"), json!(2), json!([]), json!({})] {\n            body[\"allow_bare_domains\"] = wrong;\n            assert!(Role::from_body(&body).is_err());\n        }\n        Ok(())\n    }\n\n    #[test]\n    fn pki_wildcard_syntax_and_permission_do_not_relax_historical_roles() -> Result<()> {\n        let legacy = json!({\"allowed_domains\":[\"example.test\"],\"allow_subdomains\":true,\n            \"allow_ip_sans\":false,\"max_ttl\":3600,\"generate_lease\":false});\n        let historical: Role =\n            serde_json::from_value(legacy.clone()).map_err(|_| bad(\"old role\"))?;\n        assert!(!historical.allows(\"*.example.test\"));\n        assert_eq!(\n            serde_json::to_value(&historical).map_err(|_| bad(\"old role bytes\"))?,\n            legacy\n        );\n        let current = Role::from_body(&legacy)?;\n        assert_eq!(current.allow_wildcard_certificates, Some(true));\n        for name in [\n            \"*.example.test\",\n            \"f*o.example.test\",\n            \"*foo.example.test\",\n            \"foo*.example.test\",\n        ] {\n            assert!(valid_common_name(name) && current.allows(name));\n        }\n        for name in [\n            \"**.example.test\",\n            \"a.*.example.test\",\n            \"f**o.example.test\",\n            \"-f*.example.test\",\n            \"f*-o.example.test\",\n        ] {\n            assert!(!valid_common_name(name) && !current.allows(name));\n        }\n        assert!(wildcard_dns_san(\"*.example.test\"));\n        assert!(!wildcard_dns_san(\"f*o.example.test\"));\n        let mut body = json!({\"allow_any_name\":true,\"allow_wildcard_certificates\":false});\n        let denied = Role::from_body(&body)?;\n        assert!(denied.allows(\"plain.unlisted.test\") && !denied.allows(\"*.unlisted.test\"));\n        body[\"allow_wildcard_certificates\"] = json!(\"1\");\n        assert!(Role::from_body(&body)?.allows(\"*.unlisted.test\"));\n        body[\"allow_wildcard_certificates\"] = json!(2);\n        assert!(Role::from_body(&body).is_err());\n        let mut encoded = serde_json::to_value(&current).map_err(|_| bad(\"current role bytes\"))?;\n        encoded[\"allow_wildcard_certificates\"] = json!(\"true\");\n        assert!(\n            serde_json::from_value::<Role>(encoded).is_err(),\n            \"wire coercion never relaxes durable typed bool\"\n        );\n        Ok(())\n    }\n}\n","service_native_pki_tests.rs":"//! Normal configured File V6, original PKI operations and actual local crypto.\n//! No injected Principal, fabricated root/receipt or alternate activation API.\nuse super::*;\nuse crate::configuration::NativeStorageProfile;\nuse crate::service::tests::Root;\nuse base64::engine::general_purpose::STANDARD as BASE64;\nuse openssl::{\n    hash::MessageDigest,\n    ocsp::{OcspCertId, OcspRequest},\n    pkey::PKey,\n    x509::{X509, X509Crl},\n};\nuse std::thread;\n\ntype TestResult<T = ()> = Result<T, Box<dyn std::error::Error>>;\nconst ISSUE_POLICY: &str = \"path \\\"pki/issue/web\\\" { capabilities=[\\\"update\\\"] }\";\n\n#[track_caller]\nfn status(response: &Response, expected: u16) {\n    assert_eq!(\n        response.status,\n        expected,\n        \"native PKI error shape={:?}\",\n        response.body.get(\"errors\")\n    );\n}\nfn text(response: &Response, path: &str) -> TestResult<String> {\n    response\n        .body\n        .pointer(path)\n        .and_then(Value::as_str)\n        .filter(|v| !v.is_empty())\n        .map(str::to_owned)\n        .ok_or_else(|| \"required synthetic PKI field absent\".into())\n}\nfn secret(response: &mut Response, path: &str) -> TestResult<Zeroizing<String>> {\n    let value = Zeroizing::new(text(response, path)?);\n    erase_json(&mut response.body);\n    Ok(value)\n}\nfn call(\n    service: &mut Service,\n    now: &mut u64,\n    token: &str,\n    method: &str,\n    path: &str,\n    body: Value,\n) -> TestResult<Response> {\n    *now += 1;\n    let started = Instant::now();\n    let clock = RequestClock::anchored(Duration::from_secs(*now), started)?;\n    let _deadline =\n        crate::request_deadline::RequestDeadlineScope::enter(started + Duration::from_secs(15));\n    let execution = service.begin_at_mode_precise(\n        RequestDispatch {\n            method,\n            path,\n            namespace: \"\",\n            token,\n            body,\n            now: *now,\n            allow_forward: true,\n            enforce_namespace: true,\n            wrap_ttl_seconds: None,\n            origin_peer: None,\n            client_certificates: None,\n        },\n        clock,\n    );\n    let response = service.finish_synchronous_request(execution);\n    assert!(service.pending_native_auth_delivery.is_none());\n    Ok(response)\n}\nfn role() -> Value {\n    json!({\"allowed_domains\":[\"example.test\"],\"allow_subdomains\":true,\n        \"key_type\":\"ec\",\"key_bits\":256,\"max_ttl\":\"2h\",\"generate_lease\":true})\n}\nstruct Fixture {\n    files: Root,\n    service: Service,\n    key: Zeroizing<String>,\n    admin: Zeroizing<String>,\n    now: u64,\n}\nimpl Fixture {\n    fn initialized() -> TestResult<Self> {\n        let files = Root::new();\n        let mut service = files.service()?;\n        service.configure_native_v6_storage(NativeStorageProfile::File)?;\n        let mut now = 100;\n        let mut init = call(\n            &mut service,\n            &mut now,\n            \"\",\n            \"POST\",\n            \"sys/init\",\n            json!({\"secret_shares\":1,\"secret_threshold\":1}),\n        )?;\n        status(&init, 200);\n        let key = Zeroizing::new(text(&init, \"/keys/0\")?);\n        let admin = secret(&mut init, \"/root_token\")?;\n        status(\n            &call(\n                &mut service,\n                &mut now,\n                \"\",\n                \"POST\",\n                \"sys/unseal\",\n                json!({\"key\":key.as_str()}),\n            )?,\n            200,\n        );\n        status(\n            &call(\n                &mut service,\n                &mut now,\n                &admin,\n                \"POST\",\n                \"sys/init/ack\",\n                json!({}),\n            )?,\n            204,\n        );\n        Ok(Self {\n            files,\n            service,\n            key,\n            admin,\n            now,\n        })\n    }\n    fn new() -> TestResult<Self> {\n        let mut f = Self::initialized()?;\n        status(\n            &f.admin(\"POST\", native_storage::ACTIVATE_PATH, json!({}))?,\n            204,\n        );\n        f.assert_native()?;\n        status(\n            &f.admin(\n                \"POST\",\n                \"sys/mounts/pki-kv\",\n                json!({\"type\":\"kv\",\"options\":{\"version\":\"2\"}}),\n            )?,\n            204,\n        );\n        status(\n            &f.admin(\n                \"POST\",\n                \"pki-kv/data/sentinel\",\n                json!({\"options\":{\"cas\":0},\"data\":{\"value\":\"pki-keeps-native-kv\"}}),\n            )?,\n            200,\n        );\n        f.install()?;\n        Ok(f)\n    }\n    fn install(&mut self) -> TestResult {\n        status(\n            &self.admin(\"POST\", \"sys/mounts/pki\", json!({\"type\":\"pki\"}))?,\n            204,\n        );\n        status(\n            &self.admin(\n                \"POST\",\n                \"pki/root/generate/internal\",\n                json!({\n            \"common_name\":\"ca.example.test\",\"key_type\":\"ec\",\"key_bits\":256,\"ttl\":\"48h\"}),\n            )?,\n            200,\n        );\n        status(&self.admin(\"POST\", \"pki/roles/web\", role())?, 200);\n        Ok(())\n    }\n    fn assert_native(&self) -> TestResult {\n        assert!(matches!(\n            self.service.native_storage_profile,\n            Some(NativeStorageProfile::File)\n        ));\n        assert!(self.service.native_candidate_profile.is_some());\n        assert!(self.service.native_root.is_some() && self.service.record_root.is_none());\n        assert!(!self.service.recovery_required);\n        assert!(\n            self.service\n                .state\n                .as_ref()\n                .ok_or(\"state\")?\n                .engines\n                .supports_native_v6_root_storage()\n        );\n        Ok(())\n    }\n    fn admin(&mut self, method: &str, path: &str, body: Value) -> TestResult<Response> {\n        call(\n            &mut self.service,\n            &mut self.now,\n            &self.admin,\n            method,\n            path,\n            body,\n        )\n    }\n    fn actor(\n        &mut self,\n        token: &str,\n        method: &str,\n        path: &str,\n        body: Value,\n    ) -> TestResult<Response> {\n        call(&mut self.service, &mut self.now, token, method, path, body)\n    }\n    fn restart(mut self) -> TestResult<Self> {\n        drop(self.service);\n        self.service = self.files.service()?;\n        self.service\n            .configure_native_v6_storage(NativeStorageProfile::File)?;\n        status(\n            &call(\n                &mut self.service,\n                &mut self.now,\n                \"\",\n                \"POST\",\n                \"sys/unseal\",\n                json!({\"key\":self.key.as_str()}),\n            )?,\n            200,\n        );\n        self.assert_native()?;\n        Ok(self)\n    }\n    fn root(&self) -> TestResult<RecordStateRootV6> {\n        self.service\n            .native_root\n            .clone()\n            .ok_or_else(|| \"native root\".into())\n    }\n    fn graphs_unchanged(&self, before: &RecordStateRootV6) -> TestResult {\n        let after = self.root()?;\n        assert!(before.kv1 == after.kv1 && before.kv2 == after.kv2);\n        assert_eq!(before.cluster_id, after.cluster_id);\n        assert_eq!(before.replay_epoch, after.replay_epoch);\n        Ok(())\n    }\n    fn sentinel(&mut self) -> TestResult {\n        let response = self.admin(\"GET\", \"pki-kv/data/sentinel\", json!({}))?;\n        status(&response, 200);\n        assert_eq!(response.body[\"data\"][\"metadata\"][\"version\"], 1);\n        assert_eq!(\n            response.body[\"data\"][\"data\"][\"value\"],\n            \"pki-keeps-native-kv\"\n        );\n        Ok(())\n    }\n    fn issue(&mut self, token: &str) -> TestResult<Response> {\n        let response = self.actor(\n            token,\n            \"POST\",\n            \"pki/issue/web\",\n            json!({\"common_name\":\"api.example.test\",\"ttl\":\"1h\"}),\n        )?;\n        status(&response, 200);\n        Ok(response)\n    }\n    fn policy(&mut self, name: &str, policy: &str) -> TestResult {\n        status(\n            &self.admin(\n                \"POST\",\n                &format!(\"sys/policies/acl/{name}\"),\n                json!({\"policy\":policy}),\n            )?,\n            204,\n        );\n        Ok(())\n    }\n    fn token(&mut self, policy: &str, ttl: &str) -> TestResult<Zeroizing<String>> {\n        let mut response = self.admin(\n            \"POST\",\n            \"auth/token/create\",\n            json!({\n            \"policies\":[policy],\"no_default_policy\":true,\"ttl\":ttl}),\n        )?;\n        status(&response, 200);\n        secret(&mut response, \"/auth/client_token\")\n    }\n    fn idle(&mut self, now: u64) -> TestResult<bool> {\n        self.now = now;\n        let started = Instant::now();\n        let clock = RequestClock::anchored(Duration::from_secs(now), started)?;\n        let _deadline =\n            crate::request_deadline::RequestDeadlineScope::enter(started + Duration::from_secs(15));\n        Ok(self\n            .service\n            .maintain_native_transit_with_clock_for_test(now, clock)?)\n    }\n    fn audited(\n        &mut self,\n        token: &str,\n        method: &str,\n        path: &str,\n        body: Value,\n        budget: Duration,\n    ) -> TestResult<(Response, Instant)> {\n        self.now += 1;\n        let started = Instant::now();\n        let until = started + budget;\n        let clock = RequestClock::anchored(Duration::from_secs(self.now), started)?;\n        let _deadline = crate::request_deadline::RequestDeadlineScope::enter(until);\n        let response = self.service.handle_inner(RequestView {\n            method,\n            path,\n            namespace: \"\",\n            token,\n            body: &body,\n            now: self.now,\n            admission_started: started,\n            token_clock: Some(clock),\n            allow_forward: true,\n            enforce_namespace: true,\n            wrap_ttl_seconds: None,\n            origin_peer: None,\n            client_certificates: None,\n        });\n        status(&response, 200);\n        let delivery = self\n            .service\n            .pending_native_auth_delivery\n            .as_ref()\n            .ok_or(\"actual PKI owner\")?;\n        assert!(delivery.pki_owner.is_some() && delivery.requires_local_proof());\n        assert!(delivery.tracks_terminal_checkpoint() && delivery.proof.is_none());\n        let response = self.service.audit_completed_response_with_receipt(\n            \"native-pki-actual-audit\",\n            self.now,\n            Some(clock),\n            response,\n            || {},\n        );\n        status(&response, 200);\n        let delivery = self\n            .service\n            .pending_native_auth_delivery\n            .as_ref()\n            .ok_or(\"audited PKI owner\")?;\n        assert!(matches!(\n            delivery.proof.as_ref(),\n            Some(native_v6_reader::NativeProof::Single(_))\n        ));\n        Ok((response, until))\n    }\n    fn complete(&mut self, response: Response, until: Instant) -> Response {\n        let _deadline = crate::request_deadline::RequestDeadlineScope::enter(until);\n        self.service\n            .complete_native_auth_delivery(true, response, \"pki-original-audited-delivery\")\n    }\n}\nfn verify_leaf(response: &Response) -> TestResult<(X509, X509)> {\n    let leaf = X509::from_pem(text(response, \"/data/certificate\")?.as_bytes())?;\n    let issuer = X509::from_pem(text(response, \"/data/issuing_ca\")?.as_bytes())?;\n    let issuer_key = issuer.public_key()?;\n    assert!(leaf.verify(&issuer_key)?);\n    if let Some(pem) = response.body[\"data\"][\"private_key\"].as_str() {\n        let key = PKey::private_key_from_pem(pem.as_bytes())?;\n        assert!(leaf.public_key()?.public_eq(&key));\n    }\n    Ok((leaf, issuer))\n}\nfn verify_crl(response: &Response, issuer: &X509, serial: Option<&X509>) -> TestResult {\n    status(response, 200);\n    let crl = X509Crl::from_pem(text(response, \"/data/certificate\")?.as_bytes())?;\n    let issuer_key = issuer.public_key()?;\n    assert!(crl.verify(&issuer_key)?);\n    if let Some(leaf) = serial {\n        let target = leaf.serial_number().to_bn()?.to_vec();\n        let mut found = false;\n        if let Some(revoked) = crl.get_revoked() {\n            for entry in revoked {\n                found |= entry.serial_number().to_bn()?.to_vec() == target;\n            }\n        }\n        assert!(\n            found,\n            \"actual revoked certificate serial must be in the signed CRL\"\n        );\n    }\n    Ok(())\n}\nfn private_bytes_absent(path: &std::path::Path, secret: &[u8]) -> TestResult {\n    assert!(!secret.is_empty());\n    for entry in fs::read_dir(path)? {\n        let entry = entry?;\n        let kind = entry.file_type()?;\n        assert!(!kind.is_symlink());\n        if kind.is_dir() {\n            private_bytes_absent(&entry.path(), secret)?;\n        } else if kind.is_file() {\n            let bytes = fs::read(entry.path())?;\n            assert!(!bytes.windows(secret.len()).any(|window| window == secret));\n        }\n    }\n    Ok(())\n}\nfn no_secret(response: &Response) {\n    assert_eq!(response.status, 503);\n    assert!(response.body.get(\"data\").is_none());\n    assert!(response.body.get(\"auth\").is_none());\n    assert!(response.consistency_index.is_none());\n}\n\n#[test]\nfn native_pki_formal_source_promotion_preserves_existing_signer_certificate_and_lease() -> TestResult\n{\n    let mut f = Fixture::initialized()?;\n    f.install()?;\n    let admin = Zeroizing::new(f.admin.to_string());\n    let mut issued = f.issue(&admin)?;\n    let serial = text(&issued, \"/data/serial_number\")?;\n    let certificate = text(&issued, \"/data/certificate\")?;\n    let issuer = text(&issued, \"/data/issuing_ca\")?;\n    let lease = text(&issued, \"/lease_id\")?;\n    verify_leaf(&issued)?;\n    erase_json(&mut issued.body);\n    assert!(f.service.native_root.is_none());\n    assert!(matches!(\n        f.service\n            .current_state_identity()\n            .map_err(|_| \"source identity\")?,\n        crate::state_record_root::StateIdentity::RecordsV5(_)\n    ));\n    status(\n        &f.admin(\"POST\", native_storage::ACTIVATE_PATH, json!({}))?,\n        204,\n    );\n    let mut f = f.restart()?;\n    let read = f.actor(\"\", \"GET\", &format!(\"pki/cert/{serial}\"), json!({}))?;\n    status(&read, 200);\n    assert_eq!(read.body[\"data\"][\"certificate\"], certificate);\n    status(\n        &f.admin(\"POST\", \"sys/leases/lookup\", json!({\"lease_id\":lease}))?,\n        200,\n    );\n    let mut again = f.issue(&admin)?;\n    verify_leaf(&again)?;\n    assert_eq!(again.body[\"data\"][\"issuing_ca\"], issuer);\n    erase_json(&mut again.body);\n    Ok(())\n}\n\n#[test]\nfn native_pki_formal_issue_revoke_crl_and_cold_storage_preserve_real_crypto() -> TestResult {\n    let mut f = Fixture::new()?;\n    let before = f.root()?;\n    let admin = Zeroizing::new(f.admin.to_string());\n    let mut issued = f.issue(&admin)?;\n    let (leaf, issuer) = verify_leaf(&issued)?;\n    let serial = text(&issued, \"/data/serial_number\")?;\n    let lease = text(&issued, \"/lease_id\")?;\n    let private = Zeroizing::new(text(&issued, \"/data/private_key\")?);\n    assert_eq!(issued.body[\"renewable\"], false);\n    erase_json(&mut issued.body);\n    private_bytes_absent(&f.service.data_dir, private.as_bytes())?;\n    f.graphs_unchanged(&before)?;\n    let mut f = f.restart()?;\n    status(\n        &f.admin(\"POST\", \"sys/leases/lookup\", json!({\"lease_id\":lease}))?,\n        200,\n    );\n    status(\n        &f.admin(\n            \"POST\",\n            \"sys/leases/renew\",\n            json!({\"lease_id\":lease,\"increment\":\"2h\"}),\n        )?,\n        400,\n    );\n    status(\n        &f.admin(\"POST\", \"sys/leases/revoke\", json!({\"lease_id\":lease}))?,\n        204,\n    );\n    // Inspect the installed immutable cache before any subsequent Service\n    // request can reconcile it. The actual 204 already owns the signed CRL.\n    let mut cached = f\n        .service\n        .state\n        .as_ref()\n        .ok_or(\"state\")?\n        .engines\n        .handle_public_pki_read(\"\", \"GET\", \"pki/cert/crl\", &json!({}), f.now)?\n        .ok_or(\"installed CRL cache\")?;\n    let cached = Response {\n        status: cached.status,\n        body: std::mem::take(&mut cached.body),\n        unwrapped_json: None,\n        response_headers: Default::default(),\n        consistency_index: None,\n    };\n    verify_crl(&cached, &issuer, Some(&leaf))?;\n    let observed = f.actor(\"\", \"GET\", &format!(\"pki/cert/{serial}\"), json!({}))?;\n    status(&observed, 200);\n    let revoked = observed.body[\"data\"][\"revocation_time\"]\n        .as_u64()\n        .ok_or(\"revocation\")?;\n    assert!(revoked > 0);\n    let before_rotation = f.actor(\"\", \"GET\", \"pki/cert/crl\", json!({}))?;\n    verify_crl(&before_rotation, &issuer, Some(&leaf))?;\n    let rotated = f.admin(\"GET\", \"pki/crl/rotate\", json!({}))?;\n    status(&rotated, 200);\n    assert_eq!(rotated.body[\"data\"][\"success\"], true);\n    let after_rotation = f.actor(\"\", \"GET\", \"pki/cert/crl\", json!({}))?;\n    verify_crl(&after_rotation, &issuer, Some(&leaf))?;\n    let retained_crl = text(&after_rotation, \"/data/certificate\")?;\n    assert_ne!(text(&before_rotation, \"/data/certificate\")?, retained_crl);\n    let mut f = f.restart()?;\n    let cold = f.actor(\"\", \"GET\", &format!(\"pki/cert/{serial}\"), json!({}))?;\n    status(&cold, 200);\n    assert_eq!(cold.body[\"data\"][\"revocation_time\"], revoked);\n    let cold_crl = f.actor(\"\", \"GET\", \"pki/cert/crl\", json!({}))?;\n    verify_crl(&cold_crl, &issuer, Some(&leaf))?;\n    assert_eq!(text(&cold_crl, \"/data/certificate\")?, retained_crl);\n\n    // The second original GET is also a write, with an actual pending serial\n    // outside the retained full CRL. Its real signature/cache survives reopen.\n    status(\n        &f.admin(\n            \"POST\",\n            \"pki/config/crl\",\n            json!({\"auto_rebuild\":true,\n        \"enable_delta\":true,\"expiry\":\"2h\",\"auto_rebuild_grace_period\":\"5m\",\n        \"delta_rebuild_interval\":\"1m\"}),\n        )?,\n        200,\n    );\n    let mut second = f.issue(&admin)?;\n    let (second_leaf, _) = verify_leaf(&second)?;\n    let second_lease = text(&second, \"/lease_id\")?;\n    erase_json(&mut second.body);\n    status(\n        &f.admin(\n            \"POST\",\n            \"sys/leases/revoke\",\n            json!({\"lease_id\":second_lease}),\n        )?,\n        204,\n    );\n    let rotated = f.admin(\"GET\", \"pki/crl/rotate-delta\", json!({}))?;\n    status(&rotated, 200);\n    assert_eq!(rotated.body[\"data\"][\"success\"], true);\n    let delta = f.actor(\"\", \"GET\", \"pki/cert/delta-crl\", json!({}))?;\n    verify_crl(&delta, &issuer, Some(&second_leaf))?;\n    let retained_delta = text(&delta, \"/data/certificate\")?;\n    let mut f = f.restart()?;\n    let cold_delta = f.actor(\"\", \"GET\", \"pki/cert/delta-crl\", json!({}))?;\n    verify_crl(&cold_delta, &issuer, Some(&second_leaf))?;\n    assert_eq!(text(&cold_delta, \"/data/certificate\")?, retained_delta);\n    f.sentinel()\n}\n\n#[test]\nfn native_pki_formal_no_store_has_no_phantom_lease_or_certificate() -> TestResult {\n    let mut f = Fixture::new()?;\n    let mut policy = role();\n    policy[\"no_store\"] = json!(true);\n    status(&f.admin(\"POST\", \"pki/roles/ephemeral\", policy)?, 200);\n    let before_owners = f\n        .service\n        .state\n        .as_ref()\n        .ok_or(\"state\")?\n        .engines\n        .lease_owners();\n    let mut response = f.admin(\n        \"POST\",\n        \"pki/issue/ephemeral\",\n        json!({\"common_name\":\"api.example.test\",\"ttl\":\"1h\"}),\n    )?;\n    status(&response, 200);\n    verify_leaf(&response)?;\n    assert_eq!(response.body[\"lease_id\"], \"\");\n    assert_eq!(response.body[\"lease_duration\"], 0);\n    let serial = text(&response, \"/data/serial_number\")?;\n    erase_json(&mut response.body);\n    assert!(\n        f.service\n            .state\n            .as_ref()\n            .ok_or(\"state\")?\n            .engines\n            .lease_owners()\n            == before_owners\n    );\n    let mut f = f.restart()?;\n    status(\n        &f.actor(\"\", \"GET\", &format!(\"pki/cert/{serial}\"), json!({}))?,\n        404,\n    );\n    f.sentinel()\n}\n\n#[test]\nfn native_pki_formal_intermediate_signing_keeps_actual_chain_after_cold_restart() -> TestResult {\n    let mut f = Fixture::new()?;\n    status(\n        &f.admin(\"POST\", \"sys/mounts/intermediate\", json!({\"type\":\"pki\"}))?,\n        204,\n    );\n    let generated = f.admin(\n        \"POST\",\n        \"intermediate/intermediate/generate/internal\",\n        json!({\n        \"common_name\":\"intermediate.example.test\",\"key_type\":\"ec\",\"key_bits\":256}),\n    )?;\n    status(&generated, 200);\n    let csr = text(&generated, \"/data/csr\")?;\n    let signed = f.admin(\n        \"POST\",\n        \"pki/root/sign-intermediate\",\n        json!({\"csr\":csr,\"ttl\":\"24h\"}),\n    )?;\n    status(&signed, 200);\n    let intermediate = text(&signed, \"/data/certificate\")?;\n    status(\n        &f.admin(\n            \"POST\",\n            \"intermediate/intermediate/set-signed\",\n            json!({\"certificate\":intermediate}),\n        )?,\n        200,\n    );\n    status(&f.admin(\"POST\", \"intermediate/roles/web\", role())?, 200);\n    let mut f = f.restart()?;\n    let mut issued = f.admin(\n        \"POST\",\n        \"intermediate/issue/web\",\n        json!({\"common_name\":\"api.example.test\",\"ttl\":\"1h\"}),\n    )?;\n    status(&issued, 200);\n    let (_leaf, issuer) = verify_leaf(&issued)?;\n    assert_eq!(\n        issuer.to_der()?,\n        X509::from_pem(intermediate.as_bytes())?.to_der()?\n    );\n    let root = f.actor(\"\", \"GET\", \"pki/cert/ca\", json!({}))?;\n    status(&root, 200);\n    let ca = X509::from_pem(text(&root, \"/data/certificate\")?.as_bytes())?;\n    let ca_key = ca.public_key()?;\n    assert!(issuer.verify(&ca_key)?);\n    erase_json(&mut issued.body);\n    f.sentinel()\n}\n\n#[test]\nfn native_pki_formal_public_ocsp_uses_original_anonymous_semantics_and_real_signature() -> TestResult\n{\n    let mut f = Fixture::new()?;\n    let admin = Zeroizing::new(f.admin.to_string());\n    let mut issued = f.issue(&admin)?;\n    let (leaf, issuer) = verify_leaf(&issued)?;\n    erase_json(&mut issued.body);\n    let mut request = OcspRequest::new()?;\n    request.add_id(OcspCertId::from_cert(\n        MessageDigest::sha256(),\n        &leaf,\n        &issuer,\n    )?)?;\n    let response = f.actor(\n        \"deliberately-invalid-synthetic-bearer\",\n        \"POST\",\n        \"pki/ocsp\",\n        json!({\"__heptabao_pki_ocsp_request\":BASE64.encode(request.to_der()?)}),\n    )?;\n    status(&response, 200);\n    let raw =\n        crate::engines::raw_ocsp_response(response.status, &response.body).ok_or(\"raw OCSP\")?;\n    let parsed = openssl::ocsp::OcspResponse::from_der(&raw)?;\n    assert_eq!(\n        parsed.status(),\n        openssl::ocsp::OcspResponseStatus::SUCCESSFUL\n    );\n    let mut issuers = openssl::stack::Stack::new()?;\n    issuers.push(issuer.clone())?;\n    let mut trust = openssl::x509::store::X509StoreBuilder::new()?;\n    trust.add_cert(issuer)?;\n    let mut time = openssl::x509::verify::X509VerifyParam::new()?;\n    time.set_time(f.now.try_into()?);\n    trust.set_param(&time)?;\n    parsed\n        .basic()?\n        .verify(&issuers, &trust.build(), openssl::ocsp::OcspFlag::empty())?;\n    let mut f = f.restart()?;\n    status(\n        &f.actor(\"also-invalid\", \"GET\", \"pki/cert/ca\", json!({}))?,\n        200,\n    );\n    f.sentinel()\n}\n\n#[test]\nfn native_pki_formal_audited_public_reply_status_change_is_vetoed() -> TestResult {\n    let mut f = Fixture::new()?;\n    let (mut response, until) =\n        f.audited(\"\", \"GET\", \"pki/cert/ca\", json!({}), Duration::from_secs(15))?;\n    assert!(response.body[\"data\"][\"certificate\"].is_string());\n    response.status = 503;\n    no_secret(&f.complete(response, until));\n    assert!(f.service.pending_native_auth_delivery.is_none());\n    Ok(())\n}\n\n#[test]\nfn native_pki_formal_audited_issue_rechecks_current_policy_without_resigning() -> TestResult {\n    let mut f = Fixture::new()?;\n    f.policy(\"pki-issue\", ISSUE_POLICY)?;\n    let actor = f.token(\"pki-issue\", \"600s\")?;\n    let (response, until) = f.audited(\n        &actor,\n        \"POST\",\n        \"pki/issue/web\",\n        json!({\"common_name\":\"api.example.test\",\"ttl\":\"1h\"}),\n        Duration::from_secs(15),\n    )?;\n    let serial = text(&response, \"/data/serial_number\")?;\n    let certificate = text(&response, \"/data/certificate\")?;\n    let capsule = f\n        .service\n        .pending_native_auth_delivery\n        .take()\n        .ok_or(\"original audited capsule\")?;\n    f.policy(\n        \"pki-issue\",\n        \"path \\\"pki/issue/web\\\" { capabilities=[\\\"deny\\\"] }\",\n    )?;\n    assert!(f.service.pending_native_auth_delivery.is_none());\n    f.service.pending_native_auth_delivery = Some(capsule);\n    no_secret(&f.complete(response, until));\n    let mut f = f.restart()?;\n    let issued = f.actor(\"\", \"GET\", &format!(\"pki/cert/{serial}\"), json!({}))?;\n    status(&issued, 200);\n    assert_eq!(issued.body[\"data\"][\"certificate\"], certificate);\n    let denied = f.actor(\n        &actor,\n        \"POST\",\n        \"pki/issue/web\",\n        json!({\"common_name\":\"again.example.test\",\"ttl\":\"1h\"}),\n    )?;\n    status(&denied, 403);\n    assert!(denied.body.get(\"data\").is_none());\n    f.sentinel()\n}\n\n#[test]\nfn native_pki_formal_audited_issue_cannot_refresh_original_deadline() -> TestResult {\n    let mut f = Fixture::new()?;\n    let admin = Zeroizing::new(f.admin.to_string());\n    let (response, until) = f.audited(\n        &admin,\n        \"POST\",\n        \"pki/issue/web\",\n        json!({\"common_name\":\"api.example.test\",\"ttl\":\"1h\"}),\n        Duration::from_millis(1500),\n    )?;\n    thread::sleep(until.saturating_duration_since(Instant::now()) + Duration::from_millis(20));\n    no_secret(&f.complete(response, until));\n    assert!(f.service.pending_native_auth_delivery.is_none());\n    Ok(())\n}\n\n#[test]\nfn native_pki_formal_audited_issue_retains_original_precise_issuer_expiry() -> TestResult {\n    let mut f = Fixture::new()?;\n    f.policy(\"pki-issue\", ISSUE_POLICY)?;\n    let actor = f.token(\"pki-issue\", \"2s\")?;\n    let (response, until) = f.audited(\n        &actor,\n        \"POST\",\n        \"pki/issue/web\",\n        json!({\"common_name\":\"api.example.test\",\"ttl\":\"1h\"}),\n        Duration::from_secs(15),\n    )?;\n    // This sleeps inside the same original 15-second admission, not a new one.\n    thread::sleep(Duration::from_millis(1200));\n    let denied = f.complete(response, until);\n    status(&denied, 403);\n    assert!(denied.body.get(\"data\").is_none() && denied.body.get(\"auth\").is_none());\n    assert!(denied.consistency_index.is_none());\n    Ok(())\n}\n\n#[test]\nfn native_pki_formal_idle_reconciles_actual_batch_expiry_and_persists_crl() -> TestResult {\n    let mut f = Fixture::new()?;\n    f.policy(\"pki-issue\", ISSUE_POLICY)?;\n    status(\n        &f.admin(\"POST\", \"sys/auth/up\", json!({\"type\":\"userpass\"}))?,\n        204,\n    );\n    status(\n        &f.admin(\n            \"POST\",\n            \"auth/up/users/batch\",\n            json!({\n        \"password\":\"synthetic-pki-batch-password\",\"policies\":[\"pki-issue\"],\n        \"token_type\":\"batch\",\"token_ttl\":120,\"token_max_ttl\":600,\"token_num_uses\":0}),\n        )?,\n        204,\n    );\n    let mut login = f.actor(\n        \"\",\n        \"POST\",\n        \"auth/up/login/batch\",\n        json!({\"password\":\"synthetic-pki-batch-password\"}),\n    )?;\n    status(&login, 200);\n    assert_eq!(login.body[\"auth\"][\"token_type\"], \"batch\");\n    let actor = secret(&mut login, \"/auth/client_token\")?;\n    let lookup = f.actor(&actor, \"GET\", \"auth/token/lookup-self\", json!({}))?;\n    status(&lookup, 200);\n    let expires = lookup.body[\"data\"][\"expire_time_unix\"]\n        .as_u64()\n        .ok_or(\"batch expiry\")?;\n    let mut issued = f.issue(&actor)?;\n    let (leaf, issuer) = verify_leaf(&issued)?;\n    let certificate_end = issued.body[\"data\"][\"expiration\"]\n        .as_u64()\n        .ok_or(\"leaf expiry\")?;\n    assert!(certificate_end > expires);\n    let lease_ttl = issued.body[\"lease_duration\"]\n        .as_u64()\n        .ok_or(\"batch lease TTL\")?;\n    assert!(lease_ttl > 0 && lease_ttl <= expires.saturating_sub(f.now));\n    let lease_id = text(&issued, \"/lease_id\")?;\n    let actual = f.service.state.clone().ok_or(\"actual batch PKI state\")?;\n    assert_eq!(actual.schema, AUTH_SECURITY_CONTRACT_STATE_SCHEMA);\n    assert_eq!(actual.writer_schema(), AUTH_SECURITY_CONTRACT_STATE_SCHEMA);\n    actual\n        .validate_format()\n        .map_err(|_| \"actual reader admission\")?;\n    let root = f.root()?;\n    assert_eq!(root.state_schema, AUTH_SECURITY_CONTRACT_STATE_SCHEMA);\n    assert_eq!(\n        root.reader_floor.minimum_state_schema,\n        AUTH_SECURITY_CONTRACT_STATE_SCHEMA\n    );\n    let mut historical136 = actual.clone();\n    historical136\n        .auth\n        .restore_pre141_security_owners_for_format_test();\n    historical136.schema = PKI_BATCH_LEASE_STATE_SCHEMA;\n    assert!(historical136.engines.has_pki_batch_lease_state());\n    assert!(!historical136.auth.has_security_contract_state());\n    assert!(historical136.validate_format().is_ok());\n    assert_eq!(historical136.writer_schema(), PKI_BATCH_LEASE_STATE_SCHEMA);\n    let mut lowered = historical136.clone();\n    lowered.schema = APPROLE_NO_DEFAULT_STATE_SCHEMA;\n    assert_eq!(\n        lowered\n            .validate_format()\n            .err()\n            .ok_or(\"reader downgrade\")?\n            .status,\n        503\n    );\n    assert!(lowered.validate_publication_schema(Some(&actual)).is_err());\n    assert_eq!(\n        Service::validate_snapshot_protected_floor(&actual, &lowered)\n            .err()\n            .ok_or(\"snapshot downgrade\")?\n            .status,\n        400,\n    );\n    let serial = text(&issued, \"/data/serial_number\")?;\n    erase_json(&mut issued.body);\n    let owners = f\n        .service\n        .state\n        .as_ref()\n        .ok_or(\"state\")?\n        .engines\n        .lease_owners();\n    assert!(\n        owners\n            .iter()\n            .any(|(_, owner)| owner.batch_claims().is_some())\n    );\n    let mut f = f.restart()?;\n    let lookup = f.admin(\"POST\", \"sys/leases/lookup\", json!({\"lease_id\":lease_id}))?;\n    status(&lookup, 200);\n    let retained_ttl = lookup.body[\"data\"][\"ttl\"]\n        .as_u64()\n        .ok_or(\"cold batch lease TTL\")?;\n    assert!(retained_ttl > 0 && retained_ttl <= expires.saturating_sub(f.now));\n    assert!(f.idle(expires + 1)?);\n    let mut f = f.restart()?;\n    let observed = f.actor(\"\", \"GET\", &format!(\"pki/cert/{serial}\"), json!({}))?;\n    status(&observed, 200);\n    assert!(\n        observed.body[\"data\"][\"revocation_time\"]\n            .as_u64()\n            .is_some_and(|v| v >= expires)\n    );\n    verify_crl(\n        &f.actor(\"\", \"GET\", \"pki/cert/crl\", json!({}))?,\n        &issuer,\n        Some(&leaf),\n    )?;\n    status(\n        &f.actor(\n            &actor,\n            \"POST\",\n            \"pki/issue/web\",\n            json!({\"common_name\":\"late.example.test\",\"ttl\":\"1h\"}),\n        )?,\n        403,\n    );\n    status(&f.admin(\"DELETE\", \"sys/mounts/pki\", json!({}))?, 204);\n    let mut f = f.restart()?;\n    let retired = f.service.state.as_ref().ok_or(\"retired batch PKI state\")?;\n    assert!(!retired.engines.has_pki_batch_lease_state());\n    assert_eq!(retired.schema, AUTH_SECURITY_CONTRACT_STATE_SCHEMA);\n    assert_eq!(retired.writer_schema(), AUTH_SECURITY_CONTRACT_STATE_SCHEMA);\n    assert!(retired.validate_format().is_ok());\n    assert_eq!(\n        Service::validate_snapshot_protected_floor(retired, &lowered)\n            .err()\n            .ok_or(\"retired snapshot downgrade\")?\n            .status,\n        400,\n    );\n    f.sentinel()\n}\n\n#[test]\nfn native_pki_formal_idle_checkpoint_preserves_original_transit_rotation() -> TestResult {\n    let mut f = Fixture::new()?;\n    status(\n        &f.admin(\"POST\", \"sys/mounts/transit\", json!({\"type\":\"transit\"}))?,\n        204,\n    );\n    status(\n        &f.admin(\n            \"POST\",\n            \"transit/keys/automatic\",\n            json!({\"auto_rotate_period\":\"1h\"}),\n        )?,\n        200,\n    );\n    status(\n        &f.admin(\n            \"POST\",\n            \"pki/config/crl\",\n            json!({\n        \"auto_rebuild\":true,\"expiry\":\"2h\",\"auto_rebuild_grace_period\":\"5m\"}),\n        )?,\n        200,\n    );\n    // Changing expiry does not immediately re-sign a CRL in OpenBao 2.7.1.\n    // Establish an actual two-hour CRL through the public rotation operation\n    // before testing idle rebuild and the independent Transit continuation.\n    status(&f.admin(\"GET\", \"pki/crl/rotate\", json!({}))?, 200);\n    let before = f.actor(\"\", \"GET\", \"pki/cert/crl\", json!({}))?;\n    status(&before, 200);\n    let old_crl = text(&before, \"/data/certificate\")?;\n    let cached = X509Crl::from_pem(old_crl.as_bytes())?;\n    let lifetime = cached\n        .last_update()\n        .diff(cached.next_update().ok_or(\"CRL nextUpdate\")?)?;\n    assert_eq!(\n        i64::from(lifetime.days) * 86_400 + i64::from(lifetime.secs),\n        7200\n    );\n    let before_graphs = f.root()?;\n    assert!(f.idle(f.now + 7201)?);\n    f.graphs_unchanged(&before_graphs)?;\n    let mut f = f.restart()?;\n    let key = f.admin(\"GET\", \"transit/keys/automatic\", json!({}))?;\n    status(&key, 200);\n    assert_eq!(key.body[\"data\"][\"latest_version\"], 2);\n    let new_crl = f.actor(\"\", \"GET\", \"pki/cert/crl\", json!({}))?;\n    status(&new_crl, 200);\n    assert_ne!(text(&new_crl, \"/data/certificate\")?, old_crl);\n    let ca = f.actor(\"\", \"GET\", \"pki/cert/ca\", json!({}))?;\n    status(&ca, 200);\n    verify_crl(\n        &new_crl,\n        &X509::from_pem(text(&ca, \"/data/certificate\")?.as_bytes())?,\n        None,\n    )?;\n    f.sentinel()\n}\n\nfn wire_role(f: &mut Fixture, token: &str, body: &str) -> TestResult<Response> {\n    f.now += 1;\n    let now = f.now;\n    let started = Instant::now();\n    let clock = RequestClock::anchored(Duration::from_secs(now), started)?;\n    let _deadline =\n        crate::request_deadline::RequestDeadlineScope::enter(started + Duration::from_secs(15));\n    let wire = Zeroizing::new(format!(\n        \"POST /v1/pki/roles/wire HTTP/1.1\\r\\nHost: 127.0.0.1\\r\\nX-Vault-Token: {token}\\r\\nContent-Type: application/json\\r\\nContent-Length: {}\\r\\nAccept: application/json\\r\\n\\r\\n{body}\",\n        body.len()\n    ));\n    Ok(crate::http::logical_data_wire_dispatch_fixture(\n        wire.as_bytes(),\n        |request| {\n            assert!(\n                crate::http::pki_role_fields::request(request.method, request.path, &request.body)\n                    .is_ok_and(|carrier| carrier.is_some())\n            );\n            let execution = f.service.begin_at_mode_precise(\n                RequestDispatch {\n                    method: request.method,\n                    path: request.path,\n                    namespace: request.namespace,\n                    token: request.token,\n                    body: request.body,\n                    now,\n                    allow_forward: true,\n                    enforce_namespace: true,\n                    wrap_ttl_seconds: request.wrap_ttl_seconds,\n                    origin_peer: request.origin_peer,\n                    client_certificates: request.client_certificates,\n                },\n                clock,\n            );\n            f.service.finish_synchronous_request(execution)\n        },\n    )?)\n}\n\n#[test]\nfn native_pki_formal_role_numeric_transport_preserves_original_parameter_acl() -> TestResult {\n    let mut f = Fixture::new()?;\n    let before = f.root()?;\n    // Actual OpenBao 2.7.1 HTTP/HCL comparison: numeric policy values do\n    // not equal HTTP numbers, and transport must not turn a JSON number\n    // into a string before ACL admission. Only the backend restores spelling.\n    for (allowed, spelling, expected) in [\n        (\"[256]\", \"256\", 403),\n        (\"[256]\", r#\"\"256\"\"#, 403),\n        (r#\"[\"256\"]\"#, \"256\", 403),\n        (r#\"[\"256\"]\"#, r#\"\"256\"\"#, 200),\n        (\"[]\", \"256\", 200),\n        (\"[]\", r#\"\"256\"\"#, 200),\n    ] {\n        f.policy(\n            \"pki-role\",\n            &format!(\n                r#\"path \"pki/roles/wire\" {{ capabilities=[\"create\",\"update\"] allowed_parameters={{ \"signature_bits\"={allowed} \"*\"=[] }} }}\"#\n            ),\n        )?;\n        let actor = f.token(\"pki-role\", \"600s\")?;\n        let response = wire_role(\n            &mut f,\n            &actor,\n            &format!(\n                r#\"{{\"allowed_domains\":[\"example.test\"],\"allow_subdomains\":true,\"key_type\":\"ec\",\"signature_bits\":{spelling}}}\"#\n            ),\n        )?;\n        status(&response, expected);\n        if expected == 200 {\n            let stored = f.admin(\"GET\", \"pki/roles/wire\", json!({}))?;\n            status(&stored, 200);\n            assert_eq!(stored.body[\"data\"][\"signature_bits\"], 256);\n        } else {\n            assert!(response.body.get(\"data\").is_none());\n        }\n        f.graphs_unchanged(&before)?;\n    }\n    f.sentinel()\n}\n\n#[test]\nfn native_pki_formal_selectors_retain_acme_external_and_foreign_owner_fences() -> TestResult {\n    let mut f = Fixture::new()?;\n    let before = f.root()?;\n    for path in [\n        \"pki/config/acme\",\n        \"pki/acme/new-account\",\n        \"pki/eab\",\n        \"pki/root/generate/kms\",\n        \"pki/keys/generate/kms\",\n    ] {\n        let denied = f.admin(\"POST\", path, json!({}))?;\n        status(&denied, 501);\n        assert!(denied.body.get(\"data\").is_none());\n    }\n    // Remount has a formal operation owner now. A PKI issue capability\n    // must still not authorize moving that owner or enqueue a remount task.\n    f.policy(\"pki-no-remount\", ISSUE_POLICY)?;\n    let actor = f.token(\"pki-no-remount\", \"600s\")?;\n    let denied = f.actor(\n        &actor,\n        \"POST\",\n        \"sys/remount\",\n        json!({\"from\":\"pki\",\"to\":\"other\"}),\n    )?;\n    status(&denied, 403);\n    assert!(denied.body.get(\"data\").is_none());\n    assert!(f.service.pending_native_remount.is_none());\n    assert!(f.service.native_remount_jobs.is_empty());\n    assert!(f.service.native_remount_statuses.is_empty());\n    // SSH has its own native owner; Kubernetes remains outside this profile.\n    let denied = f.admin(\"POST\", \"sys/mounts/foreign\", json!({\"type\":\"kubernetes\"}))?;\n    status(&denied, 501);\n    f.graphs_unchanged(&before)?;\n    let mut f = f.restart()?;\n    let mut issued = f.admin(\n        \"POST\",\n        \"pki/issue/web\",\n        json!({\"common_name\":\"still.example.test\",\"ttl\":\"1h\"}),\n    )?;\n    status(&issued, 200);\n    verify_leaf(&issued)?;\n    erase_json(&mut issued.body);\n    f.sentinel()\n}\n\n#[test]\nfn native_pki_formal_lease_prefix_requires_sudo_and_revocation_keeps_real_owner() -> TestResult {\n    let mut f = Fixture::new()?;\n    f.policy(\n        \"pki-prefix\",\n        \"path \\\"sys/leases/revoke-prefix/pki/\\\" { capabilities=[\\\"update\\\"] }\",\n    )?;\n    let actor = f.token(\"pki-prefix\", \"600s\")?;\n    let admin = Zeroizing::new(f.admin.to_string());\n    let mut issued = f.issue(&admin)?;\n    let (leaf, issuer) = verify_leaf(&issued)?;\n    let lease = text(&issued, \"/lease_id\")?;\n    erase_json(&mut issued.body);\n    status(\n        &f.actor(&actor, \"POST\", \"sys/leases/revoke-prefix/pki/\", json!({}))?,\n        403,\n    );\n    status(\n        &f.admin(\"POST\", \"sys/leases/lookup\", json!({\"lease_id\":lease}))?,\n        200,\n    );\n    f.policy(\n        \"pki-prefix\",\n        \"path \\\"sys/leases/revoke-prefix/pki/\\\" { capabilities=[\\\"update\\\",\\\"sudo\\\"] }\",\n    )?;\n    status(\n        &f.actor(&actor, \"POST\", \"sys/leases/revoke-prefix/pki/\", json!({}))?,\n        204,\n    );\n    verify_crl(\n        &f.actor(\"\", \"GET\", \"pki/cert/crl\", json!({}))?,\n        &issuer,\n        Some(&leaf),\n    )?;\n    let mut f = f.restart()?;\n    verify_crl(\n        &f.actor(\"\", \"GET\", \"pki/cert/crl\", json!({}))?,\n        &issuer,\n        Some(&leaf),\n    )?;\n    f.sentinel()\n}\n\n#[test]\nfn native_pki_formal_mount_tune_disable_keeps_other_graphs_and_cold_custody() -> TestResult {\n    let mut f = Fixture::new()?;\n    let before = f.root()?;\n    status(\n        &f.admin(\n            \"POST\",\n            \"sys/mounts/pki/tune\",\n            json!({\"default_lease_ttl\":\"1h\",\"max_lease_ttl\":\"4h\"}),\n        )?,\n        204,\n    );\n    let tune = f.admin(\"GET\", \"sys/mounts/pki/tune\", json!({}))?;\n    status(&tune, 200);\n    assert_eq!(tune.body[\"data\"][\"max_lease_ttl\"], 14400);\n    let mut f = f.restart()?;\n    status(&f.admin(\"DELETE\", \"sys/mounts/pki\", json!({}))?, 204);\n    f.graphs_unchanged(&before)?;\n    let mut f = f.restart()?;\n    let mounts = f.admin(\"GET\", \"sys/mounts\", json!({}))?;\n    status(&mounts, 200);\n    assert!(mounts.body[\"data\"].get(\"pki/\").is_none());\n    f.sentinel()\n}\n\n\n#[test]\nfn native_pki_formal_expired_lease_lookup_matches_openbao_271_400_and_cold() -> TestResult {\n    let mut f = Fixture::new()?;\n    let before = f.root()?;\n    let mut issued = f.admin(\n        \"POST\",\n        \"pki/issue/web\",\n        json!({\"common_name\":\"short.example.test\",\"ttl\":\"2s\"}),\n    )?;\n    status(&issued, 200);\n    let lease = text(&issued, \"/lease_id\")?;\n    let serial = text(&issued, \"/data/serial_number\")?;\n    let certificate = text(&issued, \"/data/certificate\")?;\n    assert_eq!(issued.body[\"lease_duration\"], 2);\n    erase_json(&mut issued.body);\n    status(\n        &f.admin(\"POST\", \"sys/leases/lookup\", json!({\"lease_id\":lease}))?,\n        200,\n    );\n    f.now += 3;\n    for cold in [false, true] {\n        if cold {\n            f = f.restart()?;\n        }\n        let missing = f.admin(\"POST\", \"sys/leases/lookup\", json!({\"lease_id\":lease}))?;\n        status(&missing, 400);\n        assert!(\n            missing.body[\"errors\"]\n                .as_array()\n                .is_some_and(|errors| !errors.is_empty())\n        );\n        assert!(missing.body.get(\"data\").is_none());\n        let retained = f.actor(\"\", \"GET\", &format!(\"pki/cert/{serial}\"), json!({}))?;\n        status(&retained, 200);\n        assert_eq!(retained.body[\"data\"][\"certificate\"], certificate);\n    }\n    f.graphs_unchanged(&before)?;\n    f.sentinel()\n}\n\n#[test]\nfn native_pki_formal_revoked_lease_lookup_matches_openbao_271_400_and_cold() -> TestResult {\n    let mut f = Fixture::new()?;\n    let before = f.root()?;\n    let admin = Zeroizing::new(f.admin.to_string());\n    let mut issued = f.issue(&admin)?;\n    let lease = text(&issued, \"/lease_id\")?;\n    let serial = text(&issued, \"/data/serial_number\")?;\n    let certificate = text(&issued, \"/data/certificate\")?;\n    erase_json(&mut issued.body);\n    status(\n        &f.admin(\"POST\", \"sys/leases/lookup\", json!({\"lease_id\":lease}))?,\n        200,\n    );\n    status(\n        &f.admin(\"POST\", \"sys/leases/revoke\", json!({\"lease_id\":lease,\"sync\":true}))?,\n        204,\n    );\n    for cold in [false, true] {\n        if cold {\n            f = f.restart()?;\n        }\n        let missing = f.admin(\"POST\", \"sys/leases/lookup\", json!({\"lease_id\":lease}))?;\n        status(&missing, 400);\n        assert!(\n            missing.body[\"errors\"]\n                .as_array()\n                .is_some_and(|errors| !errors.is_empty())\n        );\n        assert!(missing.body.get(\"data\").is_none());\n        let retained = f.actor(\"\", \"GET\", &format!(\"pki/cert/{serial}\"), json!({}))?;\n        status(&retained, 200);\n        assert_eq!(retained.body[\"data\"][\"certificate\"], certificate);\n    }\n    f.graphs_unchanged(&before)?;\n    f.sentinel()\n}\n\n#[path = \"service_native_pki_archive_tests.rs\"]\nmod archive;\n"}
